// A Minecraft resource pack from validated texture specs: one item model per texture, wired the 1.21.4+ way
// (assets/<ns>/items/<name>.json is what `ItemMeta.setItemModel(new NamespacedKey("<ns>", "<name>"))` points at).
// Cyrus R1 sound slice: the SAME pack also carries the mod's rendered sounds (one pack per mod, one pack.mcmeta):
//   assets/<ns>/sounds/<set>/<event>_<n>.ogg   mono Ogg Vorbis from the render host
//   assets/<ns>/sounds.json                    "<set>.<event>": { subtitle, sounds: [{ name "<ns>:<set>/<event>_<n>", weight }] }
//   assets/<ns>/lang/en_us.json                the subtitle texts (key subtitles.<ns>.<set>.<event>)
// New namespaced keys only (never `replace`, never a minecraft: key); the plugin plays "<ns>:<set>.<event>".
import { createHash } from "node:crypto";
import { checkSpec, type TextureSpec } from "./dsl";
import { encodePng } from "./png";
import { render, type Raster } from "./render";
import { checkDoc, renderDoc } from "../studios/paint";
import { displayFor } from "./display";
import { zip } from "./zip";
import { getVersion, resourcePackFormat } from "../versions/registry";

/** Resource-pack major format for a version, from the version registry. Throws for an unknown/unverified version (never guesses). */
export function packFormatFor(mc: string): number {
  const r = resourcePackFormat(mc);
  if (!r.ok) throw new Error(r.error);
  return r.format.major;
}

export type PackSoundEvent = { set: string; event: string; subtitle: string; files: { index: number; weight: number; data: Buffer }[] };
export type BuiltPack = { packFormat: number; packClientVerified: boolean; zip: Buffer; sha1: string; bytes: number; files: string[]; textures: { name: string; model: string }[]; sounds: { key: string; subtitleKey: string; files: number }[] };

const SET_RE = /^[a-z][a-z0-9_]{1,31}$/;
const EVENT_RE = /^[a-z][a-z0-9_]{0,23}$/;

export function buildPack(opts: { namespace: string; description: string; mcVersion: string; textures: unknown[]; sounds?: PackSoundEvent[]; allowPreview?: boolean }): { ok: true; pack: BuiltPack } | { ok: false; error: string } {
  if (!/^[a-z][a-z0-9_]{1,30}$/.test(opts.namespace)) return { ok: false, error: "namespace must be lowercase letters, digits and underscores" };
  const sounds = opts.sounds ?? [];
  if (opts.textures.length > 24) return { ok: false, error: "a pack holds at most 24 textures" };
  if (opts.textures.length === 0 && sounds.length === 0) return { ok: false, error: "a pack needs at least one texture or sound" };
  if (sounds.length > 24) return { ok: false, error: "a pack holds at most 24 sound events" };
  const seen = new Set<string>();
  for (const e of sounds) {
    if (!SET_RE.test(e.set) || !EVENT_RE.test(e.event)) return { ok: false, error: `bad sound key ${e.set}.${e.event}` };
    if (seen.has(`${e.set}.${e.event}`)) return { ok: false, error: `duplicate sound event ${e.set}.${e.event}` };
    seen.add(`${e.set}.${e.event}`);
    if (!e.files.length || e.files.length > 4) return { ok: false, error: `sound ${e.set}.${e.event} needs 1-4 files` };
    if (typeof e.subtitle !== "string" || e.subtitle.trim().length < 3) return { ok: false, error: `sound ${e.set}.${e.event} has no subtitle` };
    for (const f of e.files) if (f.data.subarray(0, 4).toString("latin1") !== "OggS") return { ok: false, error: `sound ${e.set}.${e.event} file ${f.index} is not Ogg` };
  }
  // Each texture is a DSL spec (what builds return) or a Texture Studio doc (spec + sparse paint layer,
  // lib/cyrus/studios/paint.ts): the pack ships the COMPOSITE pixels.
  const specs: { name: string; raster: () => Raster }[] = [];
  for (const [i, t] of opts.textures.entries()) {
    const isDoc = !!t && typeof t === "object" && (t as { v?: unknown }).v === 1 && "paint" in (t as object);
    let entry: { name: string; raster: () => Raster };
    if (isDoc) { const d = checkDoc(t); if (!d.ok) return { ok: false, error: `texture ${i + 1}: ${d.error}` }; entry = { name: d.doc.name, raster: () => renderDoc(d.doc) }; }
    else { const c = checkSpec(t); if (!c.ok) return { ok: false, error: `texture ${i + 1}: ${c.error}` }; const spec: TextureSpec = c.spec; entry = { name: spec.name, raster: () => render(spec) }; }
    if (specs.some((s) => s.name === entry.name)) return { ok: false, error: `duplicate texture name ${entry.name}` };
    specs.push(entry);
  }
  const ver = getVersion(opts.mcVersion);
  if (ver && ver.status === "preview" && !opts.allowPreview) return { ok: false, error: `${opts.mcVersion} is a preview version: its resource packs are not verified in a real client yet` };
  const pf = resourcePackFormat(opts.mcVersion, { needsItemModels: opts.textures.length > 0 });
  if (!pf.ok) return { ok: false, error: pf.error };
  const fmt = pf.format.major;
  // item model definitions need format 46+ (1.21.4); a sound-only pack also works on older versions (sounds.json is stable since 1.13)
  const minF = opts.textures.length ? 46 : Math.min(46, fmt);
  const files: { path: string; data: Buffer }[] = [
    { path: "pack.mcmeta", data: Buffer.from(JSON.stringify({ pack: { pack_format: fmt, supported_formats: { min_inclusive: minF, max_inclusive: 999 }, min_format: minF, max_format: 999, description: opts.description.slice(0, 100) } }, null, 2)) },
  ];
  const ns = opts.namespace;
  for (const s of specs) {
    const raster = s.raster();
    files.push({ path: `assets/${ns}/textures/item/${s.name}.png`, data: encodePng(raster) });
    // explicit display block (lib/cyrus/textures/display.ts): the hand transforms the studio's "In hand" preview shows
    files.push({ path: `assets/${ns}/models/item/${s.name}.json`, data: Buffer.from(JSON.stringify({ parent: "minecraft:item/handheld", textures: { layer0: `${ns}:item/${s.name}` }, display: displayFor(s.name, raster) }, null, 2)) });
    files.push({ path: `assets/${ns}/items/${s.name}.json`, data: Buffer.from(JSON.stringify({ model: { type: "minecraft:model", model: `${ns}:item/${s.name}` } }, null, 2)) });
  }
  const packSounds: BuiltPack["sounds"] = [];
  if (sounds.length) {
    const json: Record<string, unknown> = {};
    const lang: Record<string, string> = {};
    for (const e of [...sounds].sort((a, b) => (`${a.set}.${a.event}` < `${b.set}.${b.event}` ? -1 : 1))) {
      const key = `${e.set}.${e.event}`, sub = `subtitles.${ns}.${key}`;
      const list = [...e.files].sort((a, b) => a.index - b.index);
      for (const f of list) files.push({ path: `assets/${ns}/sounds/${e.set}/${e.event}_${f.index}.ogg`, data: f.data });
      json[key] = { subtitle: sub, sounds: list.map((f) => ({ name: `${ns}:${e.set}/${e.event}_${f.index}`, weight: f.weight })) };
      lang[sub] = e.subtitle.trim().slice(0, 60);
      packSounds.push({ key: `${ns}:${key}`, subtitleKey: sub, files: list.length });
    }
    files.push({ path: `assets/${ns}/sounds.json`, data: Buffer.from(JSON.stringify(json, null, 2)) });
    files.push({ path: `assets/${ns}/lang/en_us.json`, data: Buffer.from(JSON.stringify(lang, null, 2)) });
  }
  const z = zip(files);
  return { ok: true, pack: { packFormat: fmt, packClientVerified: pf.clientVerified, zip: z, sha1: createHash("sha1").update(z).digest("hex"), bytes: z.length, files: files.map((f) => f.path).sort(), textures: specs.map((s) => ({ name: s.name, model: `${ns}:${s.name}` })), sounds: packSounds } };
}
// Item model DISPLAY transforms (how a held item is placed in the hand), pure + client-safe.
// The pack builder (./pack.ts) writes them into every item model it emits, and the Texture Studio's "In hand"
// preview applies the SAME numbers (lib/cyrus/studios/held.ts), so the preview and the pack cannot drift apart.
//
// HANDHELD_DISPLAY / GENERATED_DISPLAY are the game's own `item/handheld` and `item/generated` values, checked
// 2026-10-10 against the Minecraft 1.21.4 asset mirror (github.com/InventivetalentDev/minecraft-assets, branch 1.21.4,
// assets/minecraft/models/item/{handheld,generated}.json). Numbers only: no Mojang asset is committed.
// Units: rotation in degrees (applied X, then Y, then Z: JOML rotationXYZ), translation in 1/16 block (clamped to
// +-80 by the game), scale per axis; the model (0..16 per axis) is transformed about its centre (8, 8, 8).
import type { Raster } from "./render";

export type Vec3 = [number, number, number];
export type DisplayTransform = { rotation: Vec3; translation: Vec3; scale: Vec3 };
export type DisplayView = "thirdperson_righthand" | "thirdperson_lefthand" | "firstperson_righthand" | "firstperson_lefthand";
export type Display = Record<DisplayView, DisplayTransform>;

export const HANDHELD_DISPLAY: Display = {
  thirdperson_righthand: { rotation: [0, -90, 55], translation: [0, 4.0, 0.5], scale: [0.85, 0.85, 0.85] },
  thirdperson_lefthand: { rotation: [0, 90, -55], translation: [0, 4.0, 0.5], scale: [0.85, 0.85, 0.85] },
  firstperson_righthand: { rotation: [0, -90, 25], translation: [1.13, 3.2, 1.13], scale: [0.68, 0.68, 0.68] },
  firstperson_lefthand: { rotation: [0, 90, -25], translation: [1.13, 3.2, 1.13], scale: [0.68, 0.68, 0.68] },
};
/** `item/generated` (flat items that are not tools: food, gems, drops): the hand views only. */
export const GENERATED_DISPLAY: Pick<Display, "thirdperson_righthand" | "firstperson_righthand"> = {
  thirdperson_righthand: { rotation: [0, 0, 0], translation: [0, 3, 1], scale: [0.55, 0.55, 0.55] },
  firstperson_righthand: { rotation: [0, -90, 25], translation: [1.13, 3.2, 1.13], scale: [0.68, 0.68, 0.68] },
};

/**
 * Where the hand holds the item, in model units (x right, y UP, 0..16).
 * DOCUMENTED DEFAULTS per item category (no texture marks a grip anchor yet):
 *  - "tool" (swords, pickaxes, axes, wands: anything drawn on the diagonal like vanilla): the handle end at the
 *    bottom-left, TOOL_HANDLE = (2.5, 1.5), i.e. texel (2, 14) of 16. The vanilla transforms are tuned for exactly
 *    this point, so a tool keeps the vanilla display unchanged.
 *  - "handgun" (a pistol drawn side-on, barrel to the right, grip hanging below the back of the slide): the centre of
 *    the opaque pixels in the lowest 40 % of the item's height, within its left 60 %.
 */
export type GripKind = "tool" | "handgun";
export const TOOL_HANDLE: [number, number] = [2.5, 1.5];
const GUN = /(^|_)(glock|pistol|handgun|revolver|gun|blaster|rifle|smg|shotgun|musket|flintlock|deagle|uzi)(_|$|\d)/;
export const gripKindOf = (name: string): GripKind => (GUN.test(name) ? "handgun" : "tool");

export function gripPoint(r: Raster, kind: GripKind): [number, number] {
  if (kind === "tool") return TOOL_HANDLE;
  const n = r.size, k = 16 / n;
  let x0 = n, x1 = -1, y0 = n, y1 = -1;
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) if (r.px[(y * n + x) * 4 + 3]) { x0 = Math.min(x0, x); x1 = Math.max(x1, x); y0 = Math.min(y0, y); y1 = Math.max(y1, y); }
  if (x1 < 0) return TOOL_HANDLE;
  const yCut = y1 - (y1 - y0 + 1) * 0.4, xCut = x0 + (x1 - x0 + 1) * 0.6;
  let sx = 0, sy = 0, c = 0;
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) if (r.px[(y * n + x) * 4 + 3] && y >= yCut && x <= xCut) { sx += x + 0.5; sy += y + 0.5; c++; }
  if (!c) return TOOL_HANDLE;
  return [round3((sx / c) * k), round3(16 - (sy / c) * k)];
}

const round3 = (v: number) => Math.round(v * 1000) / 1000;
const rad = (d: number) => (d * Math.PI) / 180;

/** R = Rx * Ry * Rz (JOML rotationXYZ) applied to a vector. */
export function rotate(rot: Vec3, v: Vec3): Vec3 {
  const [ax, ay, az] = rot.map(rad);
  let [x, y, z] = v;
  // Rz
  [x, y] = [x * Math.cos(az) - y * Math.sin(az), x * Math.sin(az) + y * Math.cos(az)];
  // Ry
  [x, z] = [x * Math.cos(ay) + z * Math.sin(ay), -x * Math.sin(ay) + z * Math.cos(ay)];
  // Rx
  [y, z] = [y * Math.cos(ax) - z * Math.sin(ax), y * Math.sin(ax) + z * Math.cos(ax)];
  return [x, y, z];
}

/** A model point (0..16 units) through a display transform, in 1/16 block units relative to the hand. */
export function applyDisplay(t: DisplayTransform, v: Vec3): Vec3 {
  const s: Vec3 = [(v[0] - 8) * t.scale[0], (v[1] - 8) * t.scale[1], (v[2] - 8) * t.scale[2]];
  const r = rotate(t.rotation, s);
  return [r[0] + t.translation[0], r[1] + t.translation[1], r[2] + t.translation[2]];
}

const clampT = (v: number) => round3(Math.max(-80, Math.min(80, v))) || 0; // `|| 0`: no -0 in the model JSON
/** Move a transform so that model point `g` lands where `h` did: T' = T + R S (h - g). */
export function regrip(t: DisplayTransform, g: [number, number], h: [number, number]): DisplayTransform {
  const d = rotate(t.rotation, [(h[0] - g[0]) * t.scale[0], (h[1] - g[1]) * t.scale[1], 0]);
  return { rotation: [...t.rotation], translation: [clampT(t.translation[0] + d[0]), clampT(t.translation[1] + d[1]), clampT(t.translation[2] + d[2])], scale: [...t.scale] };
}

/**
 * Handguns are drawn side-on (barrel to the right, grip below), tools on the 45 degree diagonal the vanilla transforms
 * assume, so vanilla handheld would point a pistol's barrel up / back. Cyrus's handgun rotations (right hand; the left
 * hand mirrors y and z like the game does) point the barrel forward, grip down: first person up-left toward the
 * crosshair with the pistol's side facing the camera, third person straight ahead. Found by projecting the muzzle,
 * back and grip of a side-on pistol through the same math as the preview (test/cyrus-studios.test.ts checks the
 * directions). Translation is then re-gripped. UNVERIFIED in a real client: check on the real-client test day.
 */
export const GUN_ROTATION = { firstperson: [-10, 150, 30] as Vec3, thirdperson: [0, 90, 10] as Vec3 };

/** The display block the pack writes for one item texture (tools: exactly vanilla handheld; handguns: GUN_ROTATION + re-gripped). */
export function displayFor(name: string, r: Raster): Display {
  const kind = gripKindOf(name);
  if (kind === "tool") return HANDHELD_DISPLAY;
  const g = gripPoint(r, kind);
  const H = HANDHELD_DISPLAY;
  const R = (t: DisplayTransform, r: Vec3): DisplayTransform => ({ ...t, rotation: [r[0], r[1], r[2]] });
  const L = (t: DisplayTransform, r: Vec3): DisplayTransform => ({ ...t, rotation: [r[0], -r[1], -r[2]] }); // the game mirrors y and z for the left hand
  return {
    thirdperson_righthand: regrip(R(H.thirdperson_righthand, GUN_ROTATION.thirdperson), g, TOOL_HANDLE),
    thirdperson_lefthand: regrip(L(H.thirdperson_lefthand, GUN_ROTATION.thirdperson), g, TOOL_HANDLE),
    firstperson_righthand: regrip(R(H.firstperson_righthand, GUN_ROTATION.firstperson), g, TOOL_HANDLE),
    firstperson_lefthand: regrip(L(H.firstperson_lefthand, GUN_ROTATION.firstperson), g, TOOL_HANDLE),
  };
}

