  { id: "designer-activation", file: "designer/Activation.java", purpose: "one firing: player, target, aim point, charge, budget", families: ALL, limits: ["charge clamped to 0..1"], tests: [UNIT, REAL], source: J.ACTIVATION_JAVA },
