export const COOLDOWNS_JAVA = String.raw`package __PKG__.designer;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/**
 * Component designer-cooldowns v1: per player + ability cooldowns in server ticks (Bukkit.getCurrentTick), so lag and
 * clock changes cannot shorten them. No shared state between players; entries are dropped on quit, on death and when
 * the plugin is disabled (Designer.forget / disable).
 */
public final class Cooldowns {
    private final Map<UUID, Map<String, Long>> until = new HashMap<>();

    public boolean ready(UUID player, String key, long now) { return remaining(player, key, now) <= 0; }

    public long remaining(UUID player, String key, long now) {
        Map<String, Long> m = until.get(player);
        Long t = m == null ? null : m.get(key);
        return t == null ? 0L : Math.max(0L, t - now);
    }

    public void set(UUID player, String key, long untilTick) { until.computeIfAbsent(player, k -> new HashMap<>()).put(key, untilTick); }
    public void clear(UUID player) { until.remove(player); }
    public void clearAll() { until.clear(); }
    public int players() { return until.size(); }
}
`;
export const CHARGES_JAVA = String.raw`package __PKG__.designer;

import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/**
 * Component designer-charges v1: per player + ability charges that come back one per regen period, computed lazily
 * when read (no repeating task). A player starts full. Dropped on quit / death / disable like cooldowns.
 * Semantics (the TS simulator implements exactly this): while full the regen clock does not run; after a spend from
 * full it starts at that tick; each full period adds one charge.
 */
public final class Charges {
    private static final class State { int count; long last; }
    private final Map<UUID, Map<String, State>> states = new HashMap<>();

    private State state(UUID player, String key, long now, int max) {
        Map<String, State> m = states.computeIfAbsent(player, k -> new HashMap<>());
        State s = m.get(key);
        if (s == null) { s = new State(); s.count = max; s.last = now; m.put(key, s); }
        return s;
    }

    private static void regen(State s, long now, int max, long period) {
        if (s.count >= max) { s.count = max; s.last = now; return; }
        long gained = period <= 0 ? 0 : (now - s.last) / period;
        if (gained > 0) {
            s.count = (int) Math.min(max, s.count + gained);
            s.last = s.count >= max ? now : s.last + gained * period;
        }
    }

    public int available(UUID player, String key, long now, int max, long period) {
        State s = state(player, key, now, max);
        regen(s, now, max, period);
        return s.count;
    }

    public boolean consume(UUID player, String key, long now, int max, long period, int n) {
        State s = state(player, key, now, max);
        regen(s, now, max, period);
        if (s.count < n) return false;
        s.count -= n;
        return true;
    }

    public void clear(UUID player) { states.remove(player); }
    public void clearAll() { states.clear(); }
}
`;
export const TASKS_JAVA = String.raw`package __PKG__.designer;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.bukkit.Bukkit;
import org.bukkit.plugin.Plugin;
import org.bukkit.scheduler.BukkitTask;

/**
 * Component designer-tasks v1: the only scheduler use in a designer mod. Paper main-thread scheduler (BukkitScheduler)
 * only: no async tasks, no threads, no Folia region schedulers (the registry's scheduling lane is "paper"; plugin.yml
 * does not claim folia-supported). One-shot tasks are tracked and capped (LIVE plugin-wide); timers are tracked; every
 * task is cancelled on disable and timers on /reload.
 */
public final class Tasks {
    public static final int LIVE = 128;
    private final Plugin plugin;
    private final Set<BukkitTask> live = new HashSet<>();
    private final List<BukkitTask> timers = new ArrayList<>();
    private boolean closed;

    public Tasks(Plugin plugin) { this.plugin = plugin; }

    public boolean later(long delay, Runnable step) {
        if (closed || live.size() >= LIVE) return false;
        final BukkitTask[] self = new BukkitTask[1];
        self[0] = Bukkit.getScheduler().runTaskLater(plugin, () -> { live.remove(self[0]); step.run(); }, Math.max(1L, delay));
        live.add(self[0]);
        return true;
    }

    public void timer(long period, Runnable step) {
        if (closed) return;
        long p = Math.max(10L, period);
        timers.add(Bukkit.getScheduler().runTaskTimer(plugin, step, p, p));
    }

    public void cancelTimers() { for (BukkitTask t : timers) t.cancel(); timers.clear(); }

    public void close() {
        closed = true;
        cancelTimers();
        for (BukkitTask t : new ArrayList<>(live)) t.cancel();
        live.clear();
    }

    public int live() { return live.size(); }
    public int timers() { return timers.size(); }
}
`;
