    public final String key() { return itemId + "." + id; }
    public final Trigger trigger() { return trigger; }
    public final double targetRange() { return targetRange; }
    public final long periodTicks() { return periodTicks; }
    public final long minChargeTicks() { return minChargeTicks; }
    public final boolean releaseOnRightClick() { return releaseOnRightClick; }
    public final boolean inventorySlot() { return inventorySlot; }
    public final String projectileTag() { return projectileTag; }
    public final double chargeFraction(long held) { return Math.max(0.0, Math.min(1.0, held / (double) Math.max(1L, maxChargeTicks))); }

    public abstract void load(DesignConfig c);
    protected abstract boolean check(Activation a);
    protected abstract void run(Activation a);
    public void describe(List<String> out) {}

    public final boolean cooldownReady(Player p) { return d.cooldowns().ready(p.getUniqueId(), key(), d.now()); }
    public final void startCooldown(Player p, long ticks) { if (ticks > 0) d.cooldowns().set(p.getUniqueId(), key(), d.now() + ticks); }
    public final long cooldown() { return cooldownTicks; }
    public final int chargesLeft(Player p) { return maxCharges <= 0 ? 0 : d.charges().available(p.getUniqueId(), key(), d.now(), maxCharges, chargeRegenTicks); }
    public final boolean spendCharges(Player p, int n) { return maxCharges > 0 && d.charges().consume(p.getUniqueId(), key(), d.now(), maxCharges, chargeRegenTicks, n); }

    public final boolean fire(Activation a) {
        Player p = a.player();
        // a DEATH trigger fires while the player is already dead (PlayerDeathEvent); every other trigger needs a live player
        if (!p.isOnline() || (p.isDead() && trigger != Trigger.DEATH) || !d.enter(p)) return false;
        try {
            if (!manualCooldown && cooldownTicks > 0 && !cooldownReady(p)) {
                if (feedback) p.sendActionBar(Component.text(name + ": " + String.format(java.util.Locale.ROOT, "%.1f", d.cooldowns().remaining(p.getUniqueId(), key(), d.now()) / 20.0) + "s", NamedTextColor.GRAY));
                return false;
            }
            if (!manualCharges && maxCharges > 0 && chargesLeft(p) < 1) {
                if (feedback) p.sendActionBar(Component.text(name + ": no charges", NamedTextColor.GRAY));
                return false;
            }
            if (!check(a)) return false;
            if (!manualCooldown && cooldownTicks > 0) startCooldown(p, cooldownTicks);
            if (!manualCharges && maxCharges > 0) spendCharges(p, 1);
            run(a);
            return true;
        } finally {
            d.exit(p);
        }
    }
}
`;
