// Cyrus R1: what the PORTAL does with the texture specs a succeeded build returns (called from the ModBuild sync path,
// lib/modbuilder/store.ts, so it runs in the API routes and the worker sweep alike). In order:
//   1. re-validate, render and quality-check every spec (lib/cyrus/assets/textures.ts); failures are dropped, never shipped
//   2. build the deterministic resource pack through the version registry (lib/cyrus/textures/pack.ts, NO allowPreview)
//   3. publish it to the pack store (lib/cyrus/packhost; off in production until the owner configures storage)
//   4. compute the Pack Loader entry with the pure applyPackChange
//   5. record one CyrusRevision (kind generated, manifest with jar + spec + pack hashes, engine record) and one
//      CyrusProjectAsset per texture (provenance carries the spec and its quality report)
// Sound slice (R1): returned SOUND specs are re-validated (./sounds.ts), sent to the RENDER HOST (node-2; never rendered
// here), the Oggs checked (sha256, mono Vorbis, quality bar) and added to the SAME pack with sounds.json + subtitles;
// one CyrusProjectAsset of kind "sound" per set. No render host configured -> soundRender "off" (sounds not in the pack).
// Creature pipeline (R3): returned RigSpecs are re-validated and compiled here (.bbmodel + skin, ../creature), recorded
// as CyrusProjectAsset kind "model" + manifest entries, and stored in MbAssets.creatures; they do NOT go into this pack:
// the Nxeon-managed BetterModel builds its own pack on the server (../creature/handoff.ts hosts it).
// Idempotent: re-running for the same build finds its revision (by modBuildId) and the content-addressed asset rows
// and the immutable pack object, so nothing is duplicated (the render is deterministic: same specs -> same Oggs ->
// same pack sha1). Dependencies are injected (./sync-deps.ts has the real ones).
import type { MbAssets } from "../../modbuilder/types";
import type { SvcAssetResult } from "../../modbuilder/client";
import type { AddRevisionInput, RecordAssetInput } from "../engine-core/store";
import type { ManifestEntry } from "../engine-core/revisions";
import type { StoreSelection } from "../packhost/config";
import { applyPackChange } from "../packhost/loader-config";
import { publishPack } from "../packhost/publish";
import { buildPack } from "../textures/pack";
import { QUALITY_VERSION } from "../textures/quality";
import { checkReturnedTexture, sha256Hex } from "./textures";
import { docQuality, renderDoc, TEXTURE_DOC_MIME, type TextureDoc } from "../studios/paint";
import { encodePng } from "../textures/png";
import type { RenderHostSelection } from "../sound/host";
import { checkReturnedDatapacks, DATAPACK_SPEC_MIME } from "../datapack/sync";
import { EMITTER_VERSION } from "../datapack/emit";
import { checkReturnedCreatures, RIG_SPEC_MIME } from "../creature/portal";
import { COMPILER_VERSION } from "../creature/compile";
import { SKIN_QUALITY_VERSION } from "../creature/quality";
import { checkReturnedDesigns, DESIGN_SPEC_MIME } from "../designer/sync";
import { acceptRendered, checkReturnedSound, ledgerOf, packSoundsOf, renderJobFor, SOUND_SPEC_MIME, withinBudget, type AcceptedEvent, type CheckedSound } from "./sounds";

export const PACK_ROLE = "main";
export const TEXTURE_SPEC_MIME = "application/vnd.nxeon.texture-spec+json";

export type ProjectRow = { id: string; namespace: string; userId: string };
export type AssetSyncDeps = {
  selectStore: () => StoreSelection;
  projectForRootBuild: (rootBuildId: string) => Promise<ProjectRow | null>;
  createProject: (i: { userId: string; game: string; rootBuildId: string }) => Promise<ProjectRow>;
  findRevisionForBuild: (projectId: string, modBuildId: string) => Promise<{ id: string } | null>;
  headRevisionId: (projectId: string) => Promise<string | null>;
  addRevision: (projectId: string, input: AddRevisionInput) => Promise<{ id: string }>;
  recordAsset: (projectId: string, a: RecordAssetInput) => Promise<unknown>;
  /** Sound slice. Absent = no render host (sounds stay "off"). */
  selectRenderHost?: () => RenderHostSelection;
  /** May customer builds use the owner's sound library? Absent = no. */
  soundLibraryCleared?: () => boolean;
  /**
   * Texture Studio (R1b): the project's current studio doc for a texture, if any. When the build returns a spec the
   * doc SUPERSEDES (the generated spec it was edited from, or a candidate it rejected), the doc (spec + paint layer)
   * is kept: it goes into the pack and the asset row instead of the bare spec. Absent = builds ship specs as before.
   */
  studioDocFor?: (projectId: string, name: string) => Promise<StudioDocRow | null>;
};
export type StudioDocRow = { doc: TextureDoc; sha256: string; canonical: string };

export type SyncBuild = { id: string; userId: string; rootBuildId: string | null; mcVersion: string; pluginName: string | null; jarName: string | null; jarSha256: string | null };

const clip = (s: string, n: number) => (s.length > n ? s.slice(0, n - 1) + "…" : s);

export async function syncBuildAssets(build: SyncBuild, ar: SvcAssetResult | null | undefined, deps: AssetSyncDeps): Promise<MbAssets | null> {
  if (!ar || (!ar.textures?.length && !ar.sounds?.length && !ar.datapacks?.length && !ar.designs?.length && !ar.creatures?.length && !ar.downgraded?.length)) return null;
  const root = build.rootBuildId ?? build.id;
  let project = await deps.projectForRootBuild(root);
  if (!project) {
    // A kept-texture change on a chain made before its project existed; create it (same reserved namespace rules).
    try { project = await deps.createProject({ userId: build.userId, game: "minecraft", rootBuildId: root }); }
    catch { project = await deps.projectForRootBuild(root); }
  }
  if (!project) throw new Error(`no Cyrus project for build chain ${root}`);
  const hasSounds = !!ar.sounds?.length;
  const hasCreatures = !!ar.creatures?.length;
  const base: MbAssets = { status: "none", namespace: project.namespace, projectId: project.id, revisionId: null, textures: [], ...(hasSounds ? { sounds: [], soundRender: "none" as const } : {}), dropped: [...(ar.downgraded ?? [])].map((d) => ({ name: d.name, reason: d.reason, ...(d.kind === "creature" ? { kind: "creature" as const } : d.kind === "sound" ? { kind: "sound" as const } : {}) })).slice(0, 32), pack: null, loader: null, notices: [...(ar.warnings ?? [])].slice(0, 20) };
  if (ar.namespace && ar.namespace !== project.namespace) {
    return { ...base, status: "failed", notices: [...base.notices, "The custom assets were made for a different namespace than this mod's, so they were not shipped."] };
  }

  // 1. never trust the service: validate, render and quality-check again
  const ok: Extract<ReturnType<typeof checkReturnedTexture>, { ok: true }>[] = [];
  for (const t of (ar.textures ?? []).slice(0, 24)) {
    const c = checkReturnedTexture(t);
    if (!c.ok) { base.dropped.push({ name: c.name, reason: c.reason }); base.notices.push(`Custom texture "${c.name}" was left out: it did not pass Nxeon's texture checks.`); continue; }
    if (ok.some((x) => x.name === c.name)) continue;
    ok.push(c);
  }
  // 1a. Texture Studio edits survive builds that return the spec they were made from unchanged
  const studio = new Map<string, StudioDocRow & { pngSha256: string; quality: ReturnType<typeof docQuality> }>();
  if (deps.studioDocFor) for (const c of ok) {
    const row = await deps.studioDocFor(project.id, c.name).catch(() => null);
    if (!row || row.doc.name !== c.name || !(row.doc.supersedes ?? []).includes(c.specSha256)) continue;
    const quality = docQuality(row.doc);
    if (quality.verdict === "fail") continue;
    studio.set(c.name, { ...row, quality, pngSha256: sha256Hex(encodePng(renderDoc(row.doc))) });
  }
  // 1b. sounds: re-validate (library licence policy), budget, then render on the render host and check the result
  const sndOk: Extract<CheckedSound, { ok: true }>[] = [];
