function TileCanvas({ r }: { r: Raster }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const c = ref.current; if (!c) return;
    const n = r.size; c.width = n * 3; c.height = n * 3;
    const t = document.createElement("canvas"); paintRaster(t, r, 1);
    const x = c.getContext("2d")!; x.clearRect(0, 0, c.width, c.height);
    for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) x.drawImage(t, i * n, j * n);
  }, [r]);
  return <canvas ref={ref} className="tx-tilecv" aria-label="Tiled 3 by 3" />;
}

function HeldCanvas({ r, name, view }: { r: Raster; name: string; view: HeldView }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const c = ref.current; if (!c) return;
    const W = c.clientWidth || 316, H = c.clientHeight || 150, dpr = Math.min(2, window.devicePixelRatio || 1);
    c.width = W * dpr; c.height = H * dpr;
    const x = c.getContext("2d")!; x.setTransform(dpr, 0, 0, dpr, 0, 0); x.clearRect(0, 0, W, H);
    const top = 30; // the view switch sits over the top of the stage
    x.translate(0, top);
    const s = heldScene(r, name, view, W, H - top - 4);
    x.lineJoin = "round";
    for (const p of s.polys) {
      x.beginPath(); p.pts.forEach(([a, b], i) => (i ? x.lineTo(a, b) : x.moveTo(a, b))); x.closePath();
      x.fillStyle = p.fill; x.fill();
      if (p.stroke) { x.strokeStyle = p.stroke; x.lineWidth = 1; x.stroke(); }
      else { x.strokeStyle = p.fill; x.lineWidth = 0.6; x.stroke(); } // close hairline gaps between texels
    }
  }, [r, name, view]);
  return <canvas ref={ref} className="tx-held" aria-label={`${name} held in the right hand, ${view === "firstperson" ? "first" : "third"} person`} />;
}

