// Procedural item textures, drawn by CODE (no image generation). The model never writes arbitrary drawing code:
// it writes a small declarative spec (this file's TextureSpec), and Nxeon's own renderer draws it, so the output is
// deterministic, bounded in size and time, and cannot run anything. Pure and dependency-free.

export const TEXTURE_SIZES = [16, 32, 64] as const;
export const MAX_OPS = 400;
export const MAX_PALETTE = 24;
// Creature skin sheets (Cyrus R3, lib/cyrus/creature/compile.ts): the ONLY place the limits are raised. A skin is a
// UV atlas of many box-unwrapped cubes, so it needs a bigger canvas and more (generated) ops; the item profile above
// is unchanged and stays the default. Skins have their own quality bar (lib/cyrus/creature/quality.ts).
export const SKIN_TEXTURE_SIZES = [64, 128] as const;
export const MAX_SKIN_OPS = 3000;
export const MAX_SKIN_PALETTE = 96;
export type TextureProfile = "item" | "skin";

export type Op =
  | { op: "fill"; c: string }
  | { op: "px"; x: number; y: number; c: string }
  | { op: "rect"; x: number; y: number; w: number; h: number; c: string }
  | { op: "line"; x1: number; y1: number; x2: number; y2: number; c: string }
  | { op: "circle"; x: number; y: number; r: number; c: string; ring?: boolean }
  | { op: "poly"; pts: [number, number][]; c: string }
  | { op: "gradient"; x: number; y: number; w: number; h: number; c1: string; c2: string; dir?: "v" | "h" }
  | { op: "noise"; amount: number; seed?: number; x?: number; y?: number; w?: number; h?: number }
  | { op: "shade"; amount?: number }
  | { op: "outline"; c: string };

export type TextureSpec = {
  name: string;
  size: (typeof TEXTURE_SIZES)[number] | (typeof SKIN_TEXTURE_SIZES)[number];
  palette: Record<string, string>;
  /** Draw the left half and mirror it to the right. */
  mirror?: boolean;
  ops: Op[];
};

const HEX = /^#[0-9a-fA-F]{6}$/;
const KEY = /^[a-z][a-z0-9_]{0,23}$/;
const NAME = /^[a-z][a-z0-9_]{1,31}$/;

// Generated files of the Cyrus gameplay designers (committed, so the build service needs no esbuild or zod at runtime;
// test/cyrus-designer.test.ts rebuilds them in memory and fails when one is stale):
//   services/modbuilder/designer-spec.js          the build service's validator + compiler, bundled from lib/cyrus/designer
//   lib/cyrus/designer/designer.v1.schema.json    the portable ItemDesign contract (JSON Schema)
//   npx tsx scripts/cyrus/build-designer-artifacts.ts [--check] [--out-dir DIR]   (DIR: write there instead of the repo, e.g. on a build host)
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { designJsonSchema } from "../../lib/cyrus/designer/spec";

const ROOT = path.join(__dirname, "../..");

export async function designerArtifacts(): Promise<Record<string, string>> {
  const esbuild = await import("esbuild");
  const r = await esbuild.build({
    entryPoints: [path.join(ROOT, "lib/cyrus/designer/service-entry.ts")], bundle: true, platform: "node", format: "cjs", target: "node20", write: false,
    minify: true, keepNames: true, legalComments: "none", banner: { js: `"use strict";\n// GENERATED by scripts/cyrus/build-designer-artifacts.ts from lib/cyrus/designer/*.ts (+ zod, the version registry and the data pack id lists). Do not edit.` },
  });
  return {
    "services/modbuilder/designer-spec.js": r.outputFiles[0].text,
    "lib/cyrus/designer/designer.v1.schema.json": JSON.stringify(designJsonSchema(), null, 1) + "\n",
  };
}

if (require.main === module) {
  designerArtifacts().then((files) => {
    let stale = 0;
    const oi = process.argv.indexOf("--out-dir");
    for (const [rel, text] of Object.entries(files)) {
      const abs = oi > 0 ? path.join(process.argv[oi + 1], path.basename(rel)) : path.join(ROOT, rel);
      if (process.argv.includes("--check")) {
        let cur = ""; try { cur = readFileSync(abs, "utf8"); } catch { /* missing */ }
        if (cur !== text) { stale++; console.error(`stale: ${rel}`); }
      } else { writeFileSync(abs, text); console.log(`wrote ${rel} (${Buffer.byteLength(text)} bytes)`); }
    }
    if (stale) { console.error("run: npx tsx scripts/cyrus/build-designer-artifacts.ts"); process.exit(1); }
  }).catch((e) => { console.error(e); process.exit(1); });
}
