// Cyrus R3 item model states: ItemModelSpec v1. How ONE custom item looks in each display context (hotbar/gui,
// dropped, item frame, head, first/third person hands) and which texture it shows in which STATE (a bow idle vs
// pulled back in stages, a gun idle / aiming / reloading). The build model writes one spec per stateful item at
// assets/itemmodels/<name>.json; ./emit.ts turns it into the 1.21.4+ item model definition (assets/<ns>/items/<name>.json)
// plus one model JSON per state, inside the mod's normal resource pack (lib/cyrus/textures/pack.ts).
//
// Every condition below is a VERIFIED vanilla item model property (checked 2026-10-10 against the vanilla client jars
// 1.21.4 / 1.21.11 / 26.2 and the vanilla asset mirror; exact names and thresholds in docs/DOCUMENTATION.md "Cyrus item
// model states (R3)"). Nothing is free-form: closed condition set, hard caps, the display numbers are capped like the
// game caps them (translation +-80 = 5 blocks, scale +-4; rotation is not capped by the game, Cyrus caps it at +-360).
// Validation never throws: { ok, spec, needs, warnings } | { ok: false, errors }.
// The JSON Schema (itemmodel.v1.schema.json) is generated from these Zod types (scripts/cyrus/build-itemmodel-artifacts.ts;
// a test fails while it is stale).
import { z } from "zod";
import { getVersion } from "../versions/registry";

export const ITEMMODEL_SPEC_VERSION = 1;

/** The 8 display contexts every vanilla version since 1.21.4 has (1.21.9+ adds `on_shelf`: not emitted, vanilla items do not define it either). */
export const DISPLAY_CONTEXTS = ["gui", "ground", "fixed", "head", "firstperson_righthand", "firstperson_lefthand", "thirdperson_righthand", "thirdperson_lefthand"] as const;
export type DisplayContext = (typeof DISPLAY_CONTEXTS)[number];
/** Per-category display defaults (./defaults.ts). */
export const CATEGORIES = ["sword", "tool", "bow", "crossbow", "gun", "wand", "shield", "flat"] as const;
export type Category = (typeof CATEGORIES)[number];

export const ITEMMODEL_CAPS = {
  maxStates: 8, maxTextures: 9, maxPullStages: 4, maxModes: 6, maxFlags: 4, maxDamageStages: 4, maxContextStates: 3,
  rotation: 360, translation: 80, scale: 4, pullFrom: 100, maxSpecBytes: 16 * 1024, maxSpecsPerMod: 12, labelChars: 24,
} as const;

const NAME_RE = /^[a-z][a-z0-9_]{1,31}$/; // = a texture name (lib/cyrus/textures/dsl.ts)
const KEY_RE = /^[a-z][a-z0-9_]{0,23}$/;
const C = ITEMMODEL_CAPS;

const vec = (cap: number) => z.tuple([z.number().min(-cap).max(cap), z.number().min(-cap).max(cap), z.number().min(-cap).max(cap)]);
export const TransformOverrideSchema = z.object({ rotation: vec(C.rotation).optional(), translation: vec(C.translation).optional(), scale: vec(C.scale).optional() }).strict();
export const DisplayOverrideSchema = z.object(Object.fromEntries(DISPLAY_CONTEXTS.map((c) => [c, TransformOverrideSchema.optional()])) as Record<DisplayContext, z.ZodOptional<typeof TransformOverrideSchema>>).strict();
export type DisplayOverride = z.infer<typeof DisplayOverrideSchema>;

/**
 * The closed condition set. Layer order in the emitted definition (outermost first, the first that matches wins):
 * broken -> damage -> mode -> flag -> charged -> using / pull -> selected -> context -> the idle model.
 */
export const ConditionSchema = z.discriminatedUnion("type", [
  /** the item is being used (bow drawn, shield raised, a consumable-style gun being aimed): condition minecraft:using_item */
  z.object({ type: z.literal("using") }).strict(),
  /** a pull stage while used. use_duration: range_dispatch minecraft:use_duration scale 0.05 (20 ticks = 1.0; vanilla bow 0.65 / 0.9);
   *  crossbow: minecraft:crossbow/pull (0..1 of the crossbow's charge time; vanilla 0.58 / 1.0, crossbow base only). from 0 = the first stage. */
  z.object({ type: z.literal("pull"), from: z.number().min(0).max(C.pullFrom), source: z.enum(["use_duration", "crossbow"]).optional() }).strict(),
  /** a loaded crossbow: select minecraft:charge_type (crossbow base only) */
  z.object({ type: z.literal("charged"), charge: z.enum(["arrow", "rocket"]) }).strict(),
  /** plugin-set: select minecraft:custom_model_data on strings[0] (one mode at a time: reloading, aiming, empty...) */
  z.object({ type: z.literal("mode"), value: z.string().regex(KEY_RE) }).strict(),
  /** plugin-set: condition minecraft:custom_model_data on flags[index] (index assigned in declaration order) */
  z.object({ type: z.literal("flag"), name: z.string().regex(KEY_RE) }).strict(),
  /** in the selected hotbar slot: condition minecraft:selected */
  z.object({ type: z.literal("selected") }).strict(),
  /** where it is drawn: select minecraft:display_context */
  z.object({ type: z.literal("context"), contexts: z.array(z.enum(DISPLAY_CONTEXTS)).min(1).max(7) }).strict(),
  /** one use from breaking: condition minecraft:broken */
  z.object({ type: z.literal("broken") }).strict(),
  /** worn down: range_dispatch minecraft:damage (normalised 0..1, so 0.5 = half the durability used) */
  z.object({ type: z.literal("damage"), from: z.number().gt(0).max(1) }).strict(),
]);
export type Condition = z.infer<typeof ConditionSchema>;

export const StateSchema = z.object({
  /** "idle" is the base look (the spec's own texture), so a state cannot be called idle */
  id: z.string().regex(KEY_RE),
  label: z.string().min(1).max(C.labelChars).optional(),
  /** a texture of the same mod (a TextureSpec name) */
  texture: z.string().regex(NAME_RE),
  when: ConditionSchema,
  /** per-state display overrides on top of the item's display */
  display: DisplayOverrideSchema.optional(),
}).strict();
export type ItemState = z.infer<typeof StateSchema>;

export const ItemModelSpecSchema = z.object({
  schemaVersion: z.literal(ITEMMODEL_SPEC_VERSION),
  /** = the idle texture's name AND the item model key (<ns>:<name>, what ItemMeta#setItemModel points at) */
  name: z.string().regex(NAME_RE),
  category: z.enum(CATEGORIES),
  /** owner/studio overrides on top of the category defaults (any subset of contexts and fields) */
  display: DisplayOverrideSchema.optional(),
  states: z.array(StateSchema).max(C.maxStates).optional(),
  /** the vanilla re-equip bob when the item's components change; default: off when plugin-set states exist (a mode change would bob otherwise) */
  handAnimationOnSwap: z.boolean().optional(),
}).strict();
export type ItemModelSpec = z.infer<typeof ItemModelSpecSchema>;

export type ImIssue = { path: string; code: string; message: string };
export type ItemModelNeeds = {
  /** custom_model_data strings[0] values the plugin may set (one at a time) */
  modes: string[];
  /** custom_model_data flags, index = position */
  flags: string[];
  /** the item must be usable (bow/crossbow base, or a consumable-style aim) for using/pull states to ever show */
  use: boolean;
  textures: string[];
};
export type ItemModelResult = { ok: true; spec: ItemModelSpec; needs: ItemModelNeeds; warnings: ImIssue[] } | { ok: false; errors: ImIssue[]; warnings: ImIssue[] };

const issue = (path: string, code: string, message: string): ImIssue => ({ path, code, message });

/** Where the 1.21.4 item model definitions exist (registry capability). 1.21.1 is refused with the registry's message (no legacy emitter). */
export function itemModelVersionOk(version: string): { ok: true } | { ok: false; error: string } {
  const v = getVersion(version);
  if (!v) return { ok: false, error: `Minecraft ${version} is not in the version registry` };
  if (!v.capabilities.includes("itemModelDefinitions")) return { ok: false, error: `${version} has no item model definitions (needs 1.21.4+); a legacy custom-model-data emitter is not built yet` };
  return { ok: true };
}

const USABLE: readonly Category[] = ["bow", "crossbow", "gun", "wand", "shield"];

/**
 * Validate an untrusted spec. `textures` = the texture names the mod has (absent = not checked); `version` = the
 * exact target version (absent = not checked).
 */
export function validateItemModel(raw: unknown, opts: { textures?: readonly string[]; version?: string } = {}): ItemModelResult {
  const warnings: ImIssue[] = [];
  if (raw !== null && typeof raw === "object" && Buffer.byteLength(JSON.stringify(raw)) > C.maxSpecBytes) return { ok: false, errors: [issue("(file)", "too_big", `an item model spec is at most ${C.maxSpecBytes / 1024} KB`)], warnings };
  const p = ItemModelSpecSchema.safeParse(raw);
  if (!p.success) return { ok: false, errors: p.error.issues.slice(0, 12).map((i) => issue(i.path.join(".") || "(root)", "schema", i.message)), warnings };
  const s = p.data;
  const errors: ImIssue[] = [];
  if (opts.version) { const v = itemModelVersionOk(opts.version); if (!v.ok) errors.push(issue("(version)", "version", v.error)); }
  const states = s.states ?? [];
  const ids = new Set<string>();
  const modes: string[] = [], flags: string[] = [], pulls: { from: number; source: string; i: number }[] = [], damage: number[] = [], contexts = new Set<string>();
  let using = 0, charged = new Set<string>(), selected = 0, broken = 0, ctxStates = 0;
  states.forEach((st, i) => {
    const at = `states[${i}]`;
    if (st.id === "idle") errors.push(issue(`${at}.id`, "reserved_id", `"idle" is the item's own look; name the state something else`));
    if (ids.has(st.id)) errors.push(issue(`${at}.id`, "dup_state", `two states are called ${st.id}`));
    ids.add(st.id);
    const w = st.when;
    switch (w.type) {
      case "using": using++; break;
      case "pull": {
        const source = w.source ?? "use_duration";
        if (pulls.some((x) => x.from === w.from)) errors.push(issue(`${at}.when.from`, "dup_pull", `two pull stages start at ${w.from}`));
        if (source === "crossbow" && s.category !== "crossbow") errors.push(issue(`${at}.when.source`, "crossbow_only", "crossbow pull only works on a crossbow (category crossbow)"));
        if (source === "crossbow" && w.from > 1) errors.push(issue(`${at}.when.from`, "crossbow_range", "crossbow pull runs from 0 to 1"));
        pulls.push({ from: w.from, source, i });
        break;
      }
      case "charged":
        if (s.category !== "crossbow") errors.push(issue(`${at}.when`, "crossbow_only", "a charged state only works on a crossbow (category crossbow)"));
        if (charged.has(w.charge)) errors.push(issue(`${at}.when.charge`, "dup_charged", `two states for a crossbow charged with ${w.charge}`));
        charged = new Set([...charged, w.charge]);
        break;
      case "mode": if (modes.includes(w.value)) errors.push(issue(`${at}.when.value`, "dup_mode", `two states for mode ${w.value}`)); else modes.push(w.value); break;
      case "flag": if (flags.includes(w.name)) errors.push(issue(`${at}.when.name`, "dup_flag", `two states for flag ${w.name}`)); else flags.push(w.name); break;
      case "selected": selected++; break;
      case "broken": broken++; break;
      case "damage": if (damage.includes(w.from)) errors.push(issue(`${at}.when.from`, "dup_damage", `two damage stages start at ${w.from}`)); else damage.push(w.from); break;
      case "context": {
        ctxStates++;
        for (const c of w.contexts) { if (contexts.has(c)) errors.push(issue(`${at}.when.contexts`, "context_overlap", `${c} is claimed by two states`)); contexts.add(c); }
        break;
      }
    }
  });
  if (using > 1) errors.push(issue("states", "dup_using", "at most one using state"));
  if (using && pulls.length) errors.push(issue("states", "using_and_pull", "use either one using state or pull stages, not both"));
  if (selected > 1) errors.push(issue("states", "dup_selected", "at most one selected state"));
  if (broken > 1) errors.push(issue("states", "dup_broken", "at most one broken state"));
  if (pulls.length) {
    if (!pulls.some((x) => x.from === 0)) errors.push(issue("states", "pull_no_start", "pull stages need one stage with from 0 (shown as soon as the item is used)"));
    if (new Set(pulls.map((x) => x.source)).size > 1) errors.push(issue("states", "pull_mixed", "all pull stages must use the same source"));
    if (pulls.length > C.maxPullStages) errors.push(issue("states", "too_many_pull", `at most ${C.maxPullStages} pull stages`));
  }
  if (modes.length > C.maxModes) errors.push(issue("states", "too_many_modes", `at most ${C.maxModes} modes`));
  if (flags.length > C.maxFlags) errors.push(issue("states", "too_many_flags", `at most ${C.maxFlags} flags`));
  if (damage.length > C.maxDamageStages) errors.push(issue("states", "too_many_damage", `at most ${C.maxDamageStages} damage stages`));
  if (ctxStates > C.maxContextStates) errors.push(issue("states", "too_many_context", `at most ${C.maxContextStates} context states`));
  if (contexts.size === DISPLAY_CONTEXTS.length) errors.push(issue("states", "context_all", "context states cover every context, so the item's own look would never show"));
  const textures = [s.name, ...states.map((x) => x.texture)].filter((t, i, a) => a.indexOf(t) === i);
  if (textures.length > C.maxTextures) errors.push(issue("states", "too_many_textures", `at most ${C.maxTextures} textures per item`));
  if (opts.textures) for (const [i, t] of [s.name, ...states.map((x) => x.texture)].entries()) if (!opts.textures.includes(t)) errors.push(issue(i === 0 ? "name" : `states[${i - 1}].texture`, "texture_unknown", `this mod has no texture "${t}"`));
  if ((using || pulls.length) && !USABLE.includes(s.category)) warnings.push(issue("states", "use_needs_usable_base", `using/pull states only show when the item can be used (a bow or crossbow base, or a gun/wand the plugin makes aimable); category ${s.category}`));
  if (errors.length) return { ok: false, errors, warnings };
  return { ok: true, spec: s, needs: { modes, flags, use: !!(using || pulls.length), textures }, warnings };
}

/** Several specs of one mod: each valid, names unique, at most maxSpecsPerMod. */
export function validateItemModels(raws: unknown[], opts: { textures?: readonly string[]; version?: string } = {}): { ok: boolean; results: ItemModelResult[]; errors: ImIssue[] } {
  const errors: ImIssue[] = [];
  if (raws.length > C.maxSpecsPerMod) errors.push(issue("(mod)", "too_many_specs", `at most ${C.maxSpecsPerMod} stateful items per mod`));
  const results = raws.map((r) => validateItemModel(r, opts));
  const names = results.flatMap((r) => (r.ok ? [r.spec.name] : []));
  for (const n of names) if (names.indexOf(n) !== names.lastIndexOf(n)) { errors.push(issue("(mod)", "dup_name", `two item model specs for ${n}`)); break; }
  return { ok: !errors.length && results.every((r) => r.ok), results, errors };
}

/** The portable contract (carries every cap). */
export function itemModelJsonSchema(): unknown {
  return { $id: "https://nxeon.cloud/schemas/cyrus/itemmodel.v1.json", title: "Cyrus ItemModelSpec v1", ...(z.toJSONSchema(ItemModelSpecSchema) as object) };
}

