export function validateItemModel(raw: unknown, opts: { textures?: readonly string[]; version?: string } = {}): ItemModelResult {
  const warnings: ImIssue[] = [];
  if (raw !== null && typeof raw === "object" && Buffer.byteLength(JSON.stringify(raw)) > C.maxSpecBytes) return { ok: false, errors: [issue("(file)", "too_big", `an item model spec is at most ${C.maxSpecBytes / 1024} KB`)], warnings };
  const p = ItemModelSpecSchema.safeParse(raw);
  if (!p.success) return { ok: false, errors: p.error.issues.slice(0, 12).map((i) => issue(i.path.join(".") || "(root)", "schema", i.message)), warnings };
  const s = p.data;
  const errors: ImIssue[] = [];
  if (opts.version) { const v = itemModelVersionOk(opts.version); if (!v.ok) errors.push(issue("(version)", "version", v.error)); }
  const states = s.states ?? [];
  const ids = new Set<string>();
  const modes: string[] = [], flags: string[] = [], pulls: { from: number; source: string; i: number }[] = [], damage: number[] = [], contexts = new Set<string>();
  let using = 0, charged = new Set<string>(), selected = 0, broken = 0, ctxStates = 0;
  states.forEach((st, i) => {
    const at = `states[${i}]`;
    if (st.id === "idle") errors.push(issue(`${at}.id`, "reserved_id", `"idle" is the item's own look; name the state something else`));
    if (ids.has(st.id)) errors.push(issue(`${at}.id`, "dup_state", `two states are called ${st.id}`));
    ids.add(st.id);
    const w = st.when;
    switch (w.type) {
      case "using": using++; break;
      case "pull": {
        const source = w.source ?? "use_duration";
        if (pulls.some((x) => x.from === w.from)) errors.push(issue(`${at}.when.from`, "dup_pull", `two pull stages start at ${w.from}`));
        if (source === "crossbow" && s.category !== "crossbow") errors.push(issue(`${at}.when.source`, "crossbow_only", "crossbow pull only works on a crossbow (category crossbow)"));
        if (source === "crossbow" && w.from > 1) errors.push(issue(`${at}.when.from`, "crossbow_range", "crossbow pull runs from 0 to 1"));
        pulls.push({ from: w.from, source, i });
        break;
      }
      case "charged":
        if (s.category !== "crossbow") errors.push(issue(`${at}.when`, "crossbow_only", "a charged state only works on a crossbow (category crossbow)"));
        if (charged.has(w.charge)) errors.push(issue(`${at}.when.charge`, "dup_charged", `two states for a crossbow charged with ${w.charge}`));
        charged = new Set([...charged, w.charge]);
        break;
      case "mode": if (modes.includes(w.value)) errors.push(issue(`${at}.when.value`, "dup_mode", `two states for mode ${w.value}`)); else modes.push(w.value); break;
      case "flag": if (flags.includes(w.name)) errors.push(issue(`${at}.when.name`, "dup_flag", `two states for flag ${w.name}`)); else flags.push(w.name); break;
      case "selected": selected++; break;
      case "broken": broken++; break;
      case "damage": if (damage.includes(w.from)) errors.push(issue(`${at}.when.from`, "dup_damage", `two damage stages start at ${w.from}`)); else damage.push(w.from); break;
      case "context": {
        ctxStates++;
        for (const c of w.contexts) { if (contexts.has(c)) errors.push(issue(`${at}.when.contexts`, "context_overlap", `${c} is claimed by two states`)); contexts.add(c); }
        break;
      }
    }
  });
  if (using > 1) errors.push(issue("states", "dup_using", "at most one using state"));
  if (using && pulls.length) errors.push(issue("states", "using_and_pull", "use either one using state or pull stages, not both"));
  if (selected > 1) errors.push(issue("states", "dup_selected", "at most one selected state"));
  if (broken > 1) errors.push(issue("states", "dup_broken", "at most one broken state"));
  if (pulls.length) {
    if (!pulls.some((x) => x.from === 0)) errors.push(issue("states", "pull_no_start", "pull stages need one stage with from 0 (shown as soon as the item is used)"));
    if (new Set(pulls.map((x) => x.source)).size > 1) errors.push(issue("states", "pull_mixed", "all pull stages must use the same source"));
    if (pulls.length > C.maxPullStages) errors.push(issue("states", "too_many_pull", `at most ${C.maxPullStages} pull stages`));
  }
  if (modes.length > C.maxModes) errors.push(issue("states", "too_many_modes", `at most ${C.maxModes} modes`));
  if (flags.length > C.maxFlags) errors.push(issue("states", "too_many_flags", `at most ${C.maxFlags} flags`));
  if (damage.length > C.maxDamageStages) errors.push(issue("states", "too_many_damage", `at most ${C.maxDamageStages} damage stages`));
  if (ctxStates > C.maxContextStates) errors.push(issue("states", "too_many_context", `at most ${C.maxContextStates} context states`));
  if (contexts.size === DISPLAY_CONTEXTS.length) errors.push(issue("states", "context_all", "context states cover every context, so the item's own look would never show"));
  const textures = [s.name, ...states.map((x) => x.texture)].filter((t, i, a) => a.indexOf(t) === i);
  if (textures.length > C.maxTextures) errors.push(issue("states", "too_many_textures", `at most ${C.maxTextures} textures per item`));
  if (opts.textures) for (const [i, t] of [s.name, ...states.map((x) => x.texture)].entries()) if (!opts.textures.includes(t)) errors.push(issue(i === 0 ? "name" : `states[${i - 1}].texture`, "texture_unknown", `this mod has no texture "${t}"`));
  if ((using || pulls.length) && !USABLE.includes(s.category)) warnings.push(issue("states", "use_needs_usable_base", `using/pull states only show when the item can be used (a bow or crossbow base, or a gun/wand the plugin makes aimable); category ${s.category}`));
  if (errors.length) return { ok: false, errors, warnings };
  return { ok: true, spec: s, needs: { modes, flags, use: !!(using || pulls.length), textures }, warnings };
}

/** Several specs of one mod: each valid, names unique, at most maxSpecsPerMod. */
export function validateItemModels(raws: unknown[], opts: { textures?: readonly string[]; version?: string } = {}): { ok: boolean; results: ItemModelResult[]; errors: ImIssue[] } {
  const errors: ImIssue[] = [];
  if (raws.length > C.maxSpecsPerMod) errors.push(issue("(mod)", "too_many_specs", `at most ${C.maxSpecsPerMod} stateful items per mod`));
  const results = raws.map((r) => validateItemModel(r, opts));
  const names = results.flatMap((r) => (r.ok ? [r.spec.name] : []));
  for (const n of names) if (names.indexOf(n) !== names.lastIndexOf(n)) { errors.push(issue("(mod)", "dup_name", `two item model specs for ${n}`)); break; }
  return { ok: !errors.length && results.every((r) => r.ok), results, errors };
}

/** The portable contract (carries every cap). */
export function itemModelJsonSchema(): unknown {
  return { $id: "https://nxeon.cloud/schemas/cyrus/itemmodel.v1.json", title: "Cyrus ItemModelSpec v1", ...(z.toJSONSchema(ItemModelSpecSchema) as object) };
}

