// Cyrus item model states: TEMPLATES. Each produces an ItemModelSpec plus the TextureSpecs (DSL, drawn by code) of
// every state, so a stateful item is a normal set of assets: the textures go through the texture checks and quality
// bar like any other, the spec through ./spec.ts. Used by the build prompt's example, the tests (golden hashes) and
// the studio fixtures.
//   bow:   idle + pulling_0/1/2 on minecraft:use_duration (vanilla's own thresholds 0 / 0.65 / 0.9, scale 0.05)
//   gun:   idle + aiming (using: a consumable-style aim the designer plugin adds) + reloading (mode set by the plugin)
//   sword: idle only, vanilla handheld display
//   staff: idle + charging (mode set by the plugin), handheld display (wand)
import type { TextureSpec, Op } from "../textures/dsl";
import type { ItemModelSpec } from "./spec";

export type ItemTemplate = { spec: ItemModelSpec; textures: TextureSpec[] };
export const TEMPLATE_KINDS = ["bow", "gun", "sword", "staff"] as const;
export type TemplateKind = (typeof TEMPLATE_KINDS)[number];

// ---------------------------------------------------------------------------------------------------- bow (16 px)
const BOW_PALETTE = { k: "#1c120a", w1: "#7a4a24", w2: "#b07a42", w3: "#d9a566", s: "#ece6d6", a: "#c9a06a", h: "#a9b4c2", f: "#f2f2f2" };
/** the limb arc, tip (3,1) to tip (14,12), bulging to the top right */
const BOW_ARC: Op[] = [
  { op: "line", x1: 3, y1: 1, x2: 8, y2: 1, c: "w1" }, { op: "line", x1: 8, y1: 1, x2: 11, y2: 3, c: "w1" },
  { op: "line", x1: 11, y1: 3, x2: 13, y2: 6, c: "w1" }, { op: "line", x1: 13, y1: 6, x2: 14, y2: 12, c: "w1" },
  { op: "line", x1: 4, y1: 2, x2: 8, y2: 2, c: "w2" }, { op: "line", x1: 9, y1: 2, x2: 11, y2: 4, c: "w2" }, { op: "line", x1: 12, y1: 5, x2: 13, y2: 9, c: "w2" },
  { op: "rect", x: 10, y: 3, w: 2, h: 2, c: "w3" }, // the grip wrap
];
/** string from both tips through the nock point P; an arrow from P toward the top right when drawn */
function bowTexture(name: string, nock: [number, number] | null): TextureSpec {
  const [px, py] = nock ?? [0, 0];
  const string: Op[] = nock
    ? [{ op: "line", x1: 3, y1: 2, x2: px, y2: py, c: "s" }, { op: "line", x1: px, y1: py, x2: 13, y2: 12, c: "s" }]
    : [{ op: "line", x1: 3, y1: 2, x2: 13, y2: 12, c: "s" }];
  const arrow: Op[] = nock ? [
    { op: "line", x1: px, y1: py, x2: Math.min(15, px + 9), y2: Math.max(0, py - 9), c: "a" },
    { op: "px", x: Math.min(15, px + 9), y: Math.max(0, py - 9), c: "h" }, { op: "px", x: Math.min(15, px + 8), y: Math.max(0, py - 9), c: "h" }, { op: "px", x: Math.min(15, px + 9), y: Math.max(0, py - 8), c: "h" },
    { op: "px", x: px, y: py - 1, c: "f" }, { op: "px", x: px + 1, y: py, c: "f" },
  ] : [];
  return { name, size: 16, palette: { ...BOW_PALETTE }, ops: [...BOW_ARC, ...string, ...arrow, { op: "outline", c: "k" }] };
}

export function bowTemplate(name = "hunter_bow"): ItemTemplate {
  const stages: [string, [number, number]][] = [["pulling_0", [7, 7]], ["pulling_1", [5, 9]], ["pulling_2", [3, 11]]];
  return {
    spec: {
      schemaVersion: 1, name, category: "bow",
      states: [
        { id: "pulling_0", label: "Pull 1", texture: `${name}_pulling_0`, when: { type: "pull", from: 0 } },
        { id: "pulling_1", label: "Pull 2", texture: `${name}_pulling_1`, when: { type: "pull", from: 0.65 } },
        { id: "pulling_2", label: "Pull 3", texture: `${name}_pulling_2`, when: { type: "pull", from: 0.9 } },
      ],
    },
    textures: [bowTexture(name, null), ...stages.map(([id, p]) => bowTexture(`${name}_${id}`, p))],
  };
}

// ---------------------------------------------------------------------------------------------------- gun (16 px)
const GUN_PALETTE = { k: "#0d0f14", b1: "#3a404c", b2: "#5a6272", b3: "#8a93a6", g1: "#2a2018", g2: "#4a3828", r: "#ff3b4a", m: "#6a7488", y: "#ffd34a" };
function gunTexture(name: string, variant: "idle" | "aiming" | "reloading"): TextureSpec {
  const slideBack = variant === "reloading" ? -2 : 0;
  const ops: Op[] = [
    { op: "rect", x: 2 + slideBack, y: 4, w: 12, h: 3, c: "b2" }, // slide
    { op: "line", x1: 2 + slideBack, y1: 4, x2: 13 + slideBack, y2: 4, c: "b3" },
    { op: "rect", x: 3, y: 7, w: 10, h: 1, c: "b1" }, // frame
    { op: "rect", x: 14 + slideBack, y: 5, w: 1, h: 1, c: "b1" }, // muzzle
    { op: "poly", pts: [[3, 8], [7, 8], [6, 13], [2, 13]], c: "g1" }, // grip
    { op: "line", x1: 4, y1: 9, x2: 3, y2: 12, c: "g2" },
    { op: "line", x1: 8, y1: 8, x2: 9, y2: 10, c: "b1" }, { op: "line", x1: 9, y1: 10, x2: 7, y2: 10, c: "b1" }, // trigger guard
    { op: "px", x: 12 + slideBack, y: 3, c: "b3" }, // front sight
  ];
  if (variant === "aiming") ops.push({ op: "px", x: 4, y: 3, c: "r" }, { op: "px", x: 12, y: 3, c: "r" }, { op: "px", x: 15, y: 5, c: "y" });
  if (variant === "reloading") ops.push({ op: "rect", x: 3, y: 14, w: 3, h: 2, c: "m" }, { op: "px", x: 4, y: 14, c: "y" }); // the magazine dropping out
  ops.push({ op: "outline", c: "k" });
  return { name, size: 16, palette: { ...GUN_PALETTE }, ops };
}

export function gunTemplate(name = "service_pistol"): ItemTemplate {
  return {
    spec: {
      schemaVersion: 1, name, category: "gun",
      states: [
        // reloading is a plugin-set mode: it wins over aiming (layer order mode > using)
        { id: "reloading", label: "Reload", texture: `${name}_reloading`, when: { type: "mode", value: "reloading" } },
        // aiming: the gun is "used" (a consumable-style hold the designer adds), raised toward the screen centre in first person
        { id: "aiming", label: "Aim", texture: `${name}_aiming`, when: { type: "using" }, display: { firstperson_righthand: { translation: [-2, 4.5, -1] } } },
      ],
    },
    textures: [gunTexture(name, "idle"), gunTexture(`${name}_aiming`, "aiming"), gunTexture(`${name}_reloading`, "reloading")],
  };
}

// --------------------------------------------------------------------------------------------- sword + staff (16 px)
const SWORD_PALETTE = { k: "#0a1424", b1: "#e6f4ff", b2: "#9fc4e0", b3: "#5a82a8", g: "#c9a24a", h: "#5a3a22", hh: "#7d5532" };
export function swordTemplate(name = "steel_sword"): ItemTemplate {
  return {
    spec: { schemaVersion: 1, name, category: "sword" },
    textures: [{
      name, size: 16, palette: { ...SWORD_PALETTE },
      ops: [
        { op: "poly", pts: [[5, 10], [6, 11], [14, 3], [14, 1], [12, 2]], c: "b2" },
        { op: "line", x1: 6, y1: 10, x2: 13, y2: 2, c: "b1" },
        { op: "line", x1: 7, y1: 11, x2: 14, y2: 4, c: "b3" },
        { op: "line", x1: 3, y1: 9, x2: 7, y2: 13, c: "g" }, // guard
        { op: "line", x1: 4, y1: 12, x2: 2, y2: 14, c: "h" }, { op: "line", x1: 5, y1: 12, x2: 3, y2: 14, c: "hh" },
        { op: "outline", c: "k" },
      ],
    }],
  };
}

const STAFF_PALETTE = { k: "#120a1e", w1: "#5a3a22", w2: "#8a5a32", o1: "#6a4cff", o2: "#a68bff", o3: "#e6dcff", c: "#35e3ff" };
function staffTexture(name: string, charging: boolean): TextureSpec {
  const ops: Op[] = [
    { op: "line", x1: 2, y1: 14, x2: 10, y2: 6, c: "w1" }, { op: "line", x1: 3, y1: 14, x2: 11, y2: 6, c: "w2" },
    { op: "circle", x: 12, y: 4, r: 2, c: charging ? "c" : "o1" }, { op: "px", x: 12, y: 3, c: charging ? "o3" : "o2" }, { op: "px", x: 11, y: 4, c: "o3" },
  ];
  if (charging) ops.push({ op: "px", x: 15, y: 1, c: "c" }, { op: "px", x: 9, y: 1, c: "o2" }, { op: "px", x: 15, y: 6, c: "o2" });
  ops.push({ op: "outline", c: "k" });
  return { name, size: 16, palette: { ...STAFF_PALETTE }, ops };
}
export function staffTemplate(name = "storm_staff"): ItemTemplate {
  return {
    spec: { schemaVersion: 1, name, category: "wand", states: [{ id: "charging", label: "Charging", texture: `${name}_charging`, when: { type: "mode", value: "charging" } }] },
    textures: [staffTexture(name, false), staffTexture(`${name}_charging`, true)],
  };
}

export function itemTemplate(kind: TemplateKind, name?: string): ItemTemplate {
  return kind === "bow" ? bowTemplate(name) : kind === "gun" ? gunTemplate(name) : kind === "sword" ? swordTemplate(name) : staffTemplate(name);
}

