/** the limb arc, tip (3,1) to tip (14,12), bulging to the top right */
const BOW_ARC: Op[] = [
  { op: "line", x1: 3, y1: 1, x2: 8, y2: 1, c: "w1" }, { op: "line", x1: 8, y1: 1, x2: 11, y2: 3, c: "w1" },
  { op: "line", x1: 11, y1: 3, x2: 13, y2: 6, c: "w1" }, { op: "line", x1: 13, y1: 6, x2: 14, y2: 12, c: "w1" },
  { op: "line", x1: 4, y1: 2, x2: 8, y2: 2, c: "w2" }, { op: "line", x1: 9, y1: 2, x2: 11, y2: 4, c: "w2" }, { op: "line", x1: 12, y1: 5, x2: 13, y2: 9, c: "w2" },
  { op: "rect", x: 10, y: 3, w: 2, h: 2, c: "w3" }, // the grip wrap
];
/** string from both tips through the nock point P; an arrow from P toward the top right when drawn */
function bowTexture(name: string, nock: [number, number] | null): TextureSpec {
  const [px, py] = nock ?? [0, 0];
  const string: Op[] = nock
    ? [{ op: "line", x1: 3, y1: 2, x2: px, y2: py, c: "s" }, { op: "line", x1: px, y1: py, x2: 13, y2: 12, c: "s" }]
    : [{ op: "line", x1: 3, y1: 2, x2: 13, y2: 12, c: "s" }];
  const arrow: Op[] = nock ? [
    { op: "line", x1: px, y1: py, x2: Math.min(15, px + 9), y2: Math.max(0, py - 9), c: "a" },
    { op: "px", x: Math.min(15, px + 9), y: Math.max(0, py - 9), c: "h" }, { op: "px", x: Math.min(15, px + 8), y: Math.max(0, py - 9), c: "h" }, { op: "px", x: Math.min(15, px + 9), y: Math.max(0, py - 8), c: "h" },
    { op: "px", x: px, y: py - 1, c: "f" }, { op: "px", x: px + 1, y: py, c: "f" },
