export function gunTemplate(name = "service_pistol"): ItemTemplate {
  return {
    spec: {
      schemaVersion: 1, name, category: "gun",
      states: [
        // reloading is a plugin-set mode: it wins over aiming (layer order mode > using)
        { id: "reloading", label: "Reload", texture: `${name}_reloading`, when: { type: "mode", value: "reloading" } },
