const STAFF_PALETTE = { k: "#120a1e", w1: "#5a3a22", w2: "#8a5a32", o1: "#6a4cff", o2: "#a68bff", o3: "#e6dcff", c: "#35e3ff" };
function staffTexture(name: string, charging: boolean): TextureSpec {
  const ops: Op[] = [
    { op: "line", x1: 2, y1: 14, x2: 10, y2: 6, c: "w1" }, { op: "line", x1: 3, y1: 14, x2: 11, y2: 6, c: "w2" },
    { op: "circle", x: 12, y: 4, r: 2, c: charging ? "c" : "o1" }, { op: "px", x: 12, y: 3, c: charging ? "o3" : "o2" }, { op: "px", x: 11, y: 4, c: "o3" },
