s=s.replace('''export function buildPack(opts: { namespace: string; description: string; mcVersion: string; textures: unknown[]; sounds?: PackSoundEvent[]; allowPreview?: boolean }): { ok: true; pack: BuiltPack } | { ok: false; error: string } {''','''/**
 * `itemModels` (Cyrus item model states, optional): ItemModelSpec v1 objects. Each spec's idle texture and state
