EOF
cat > scripts/cyrus/build-itemmodel-artifacts.ts <<'EOF'
// Generated files of the Cyrus item model states (committed, so the build service needs no esbuild or zod at runtime;
// test/cyrus-itemmodel.test.ts rebuilds them in memory and fails when one is stale):
//   services/modbuilder/itemmodel-spec.js          the build service's validator + emitter, bundled from lib/cyrus/itemmodel
//   lib/cyrus/itemmodel/itemmodel.v1.schema.json   the portable ItemModelSpec contract (JSON Schema)
//   npx tsx scripts/cyrus/build-itemmodel-artifacts.ts [--check] [--out-dir DIR]
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { itemModelJsonSchema } from "../../lib/cyrus/itemmodel/spec";

const ROOT = path.join(__dirname, "../..");

export async function itemModelArtifacts(): Promise<Record<string, string>> {
  const esbuild = await import("esbuild");
  const r = await esbuild.build({
    entryPoints: [path.join(ROOT, "lib/cyrus/itemmodel/service-entry.ts")], bundle: true, platform: "node", format: "cjs", target: "node20", write: false,
    minify: true, keepNames: true, legalComments: "none", banner: { js: `"use strict";\n// GENERATED by scripts/cyrus/build-itemmodel-artifacts.ts from lib/cyrus/itemmodel/*.ts (+ zod and the version registry). Do not edit.` },
  });
  return {
    "services/modbuilder/itemmodel-spec.js": r.outputFiles[0].text,
    "lib/cyrus/itemmodel/itemmodel.v1.schema.json": JSON.stringify(itemModelJsonSchema(), null, 1) + "\n",
  };
}

if (require.main === module) {
  itemModelArtifacts().then((files) => {
    let stale = 0;
    const oi = process.argv.indexOf("--out-dir");
    for (const [rel, text] of Object.entries(files)) {
      const abs = oi > 0 ? path.join(process.argv[oi + 1], rel) : path.join(ROOT, rel);
      if (process.argv.includes("--check")) {
        let cur = ""; try { cur = readFileSync(abs, "utf8"); } catch { /* missing */ }
        if (cur !== text) { stale++; console.error(`stale: ${rel}`); }
      } else { writeFileSync(abs, text); console.log(`wrote ${rel} (${Buffer.byteLength(text)} bytes)`); }
    }
    if (stale) { console.error("run: npx tsx scripts/cyrus/build-itemmodel-artifacts.ts"); process.exit(1); }
  }).catch((e) => { console.error(e); process.exit(1); });
}
EOF
