// Cyrus item model states: the designer component that sets custom_model_data on held design items from ability
// states (and gives aimable items their consumable-style "using" hold). Emitted ONLY into mods whose designs declare
// `states` on a version with item models (1.21.4+), so every existing designer mod keeps its exact bytes (golden hashes)
// and the library hash of the 17 components is unchanged. API names javap-verified 2026-10-10 on node-2 against
// paper-api 1.21.11-R0.1-SNAPSHOT and 26.2.build.133-stable:
//   ItemMeta#getCustomModelDataComponent / #setCustomModelDataComponent / #hasCustomModelDataComponent / #getAsComponentString
//   org.bukkit.inventory.meta.components.CustomModelDataComponent#getFlags/#setFlags(List<Boolean>)/#getStrings/#setStrings(List<String>)
//   io.papermc.paper.datacomponent.DataComponentTypes.CONSUMABLE (@ApiStatus.Experimental on 1.21.11, @MinecraftVersionDependent on 26.2)
//   io.papermc.paper.datacomponent.item.Consumable.consumable() -> Builder#consumeSeconds(float)/#animation/#sound(Key)/#hasConsumeParticles(boolean)
//   io.papermc.paper.datacomponent.item.consumable.ItemUseAnimation.{NONE,BOW,CROSSBOW,SPYGLASS}; ItemStack#setData/#hasData
//   org.bukkit.event.player.PlayerItemConsumeEvent (Cancellable)
import type { ComponentMeta } from "./index";

export const MODEL_STATES_JAVA = String.raw`package __PKG__.designer;

import io.papermc.paper.datacomponent.DataComponentTypes;
import io.papermc.paper.datacomponent.item.Consumable;
import io.papermc.paper.datacomponent.item.consumable.ItemUseAnimation;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.kyori.adventure.key.Key;
import org.bukkit.Bukkit;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerItemConsumeEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.inventory.meta.components.CustomModelDataComponent;
import org.bukkit.scheduler.BukkitTask;

/**
 * Component designer-model-states v1: item model states. Every PERIOD ticks (main thread) the design items in each
 * online player's hands get custom_model_data from their ability states: a MODE rule sets strings[0] (the first active
 * mode wins; none = no string), a FLAG rule sets flags[index]. Nothing active = the component is removed, so an item
 * at rest is the same stack as a fresh one. The item model definition in the mod's resource pack (Cyrus item model
 * states) picks the texture from these values. Aimable items get minecraft:consumable with a one-hour hold, no sound
 * and no particles, so holding right-click "uses" them (the item model's using / pull states); this component is the
 * ONE place that cancels an event: an aimable design item is never eaten (PlayerItemConsumeEvent, own items only).
 * Items that are not in a hand keep their last state until held again.
 */
public final class ModelStates implements Listener {
    public static final long PERIOD = 2L;
    public static final float AIM_SECONDS = 3600.0f;
    public enum During { COOLDOWN, NO_CHARGES, CHARGING }
    /** mode != null: a mode rule; else a flag rule for flags[flag]. */
    public record Rule(String item, String ability, During during, String mode, int flag) {}

    private final Designer d;
    private final List<Rule> rules;
    private final Map<String, Integer> flagCounts;
    private final Set<String> aimItems;
    private BukkitTask task;

    public ModelStates(Designer d, List<Rule> rules, Map<String, Integer> flagCounts, Set<String> aimItems) {
        this.d = d;
        this.rules = List.copyOf(rules);
        this.flagCounts = Map.copyOf(flagCounts);
        this.aimItems = Set.copyOf(aimItems);
    }

    public void start() {
        d.plugin().getServer().getPluginManager().registerEvents(this, d.plugin());
        if (!rules.isEmpty()) task = Bukkit.getScheduler().runTaskTimer(d.plugin(), this::tick, PERIOD, PERIOD);
        selfCheck();
    }

    public void stop() {
        if (task != null) task.cancel();
        task = null;
    }

    /** Make an item "usable" by holding right-click (a consumable that never finishes; see the class comment). */
    public static void aimable(ItemStack s, ItemUseAnimation animation) {
        s.setData(DataComponentTypes.CONSUMABLE, Consumable.consumable().consumeSeconds(AIM_SECONDS).animation(animation).sound(Key.key("minecraft", "intentionally_empty")).hasConsumeParticles(false));
    }

    /** Set strings[0] = mode (null = none) and the flags; removes the component when nothing is set. True when the stack changed. */
    public static boolean apply(ItemStack s, String mode, List<Boolean> flags) {
        ItemMeta m = s.getItemMeta();
        if (m == null) return false;
        boolean any = mode != null || flags.contains(Boolean.TRUE);
        if (!any) {
            if (!m.hasCustomModelDataComponent()) return false;
            m.setCustomModelDataComponent(null);
            s.setItemMeta(m);
            return true;
        }
        CustomModelDataComponent c = m.getCustomModelDataComponent();
        List<String> strings = mode == null ? List.of() : List.of(mode);
        if (m.hasCustomModelDataComponent() && c.getStrings().equals(strings) && c.getFlags().equals(flags)) return false;
        c.setStrings(strings);
        c.setFlags(flags);
        m.setCustomModelDataComponent(c);
        s.setItemMeta(m);
        return true;
    }

    private void tick() {
        for (Player p : Bukkit.getOnlinePlayers()) {
            if (p.isDead()) continue;
            refresh(p, p.getInventory().getItemInMainHand());
            refresh(p, p.getInventory().getItemInOffHand());
        }
    }

    private void refresh(Player p, ItemStack s) {
        String id = d.identity().idOf(s);
        if (id == null) return;
        Integer n = flagCounts.get(id);
        if (n == null) return;
        String mode = null;
        List<Boolean> flags = new ArrayList<>(Collections.nCopies(n, Boolean.FALSE));
        for (Rule r : rules) {
            if (!r.item().equals(id) || !active(p, r)) continue;
            if (r.mode() != null) { if (mode == null) mode = r.mode(); }
            else if (r.flag() >= 0 && r.flag() < n) flags.set(r.flag(), Boolean.TRUE);
        }
        apply(s, mode, flags);
    }

    private boolean active(Player p, Rule r) {
        Ability a = d.ability(r.item(), r.ability());
        if (a == null) return false;
        return switch (r.during()) {
            case COOLDOWN -> a.cooldown() > 0 && !a.cooldownReady(p);
            case NO_CHARGES -> a.chargesLeft(p) < 1;
            case CHARGING -> a.trigger() == Trigger.CHARGE_RELEASE && d.chargeStart(p.getUniqueId()) != null;
        };
    }

    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = true)
    public void onConsume(PlayerItemConsumeEvent e) {
        String id = d.identity().idOf(e.getItem());
        if (id != null && aimItems.contains(id)) e.setCancelled(true);
    }

    /** At enable: build each stateful item, set and clear every state on it, and log what the stack really carries. */
    private void selfCheck() {
        List<String> ids = new ArrayList<>();
        for (Rule r : rules) if (!ids.contains(r.item())) ids.add(r.item());
        for (String a : aimItems) if (!ids.contains(a)) ids.add(a);
        Collections.sort(ids);
        for (String id : ids) {
            DesignItem item = d.item(id);
            if (item == null) continue;
            StringBuilder out = new StringBuilder("model states " + id + ":");
            try {
                ItemStack s = item.create();
                int n = flagCounts.getOrDefault(id, 0);
                String shown = null;
                for (Rule r : rules) {
                    if (!r.item().equals(id)) continue;
                    List<Boolean> flags = new ArrayList<>(Collections.nCopies(n, Boolean.FALSE));
                    if (r.mode() == null && r.flag() >= 0 && r.flag() < n) flags.set(r.flag(), Boolean.TRUE);
                    apply(s, r.mode(), flags);
                    ItemMeta m = s.getItemMeta();
                    CustomModelDataComponent c = m.getCustomModelDataComponent();
                    boolean ok = r.mode() != null ? c.getStrings().equals(List.of(r.mode())) : c.getFlags().equals(flags);
                    out.append(r.mode() != null ? " mode " + r.mode() : " flag " + r.flag()).append(ok ? "=ok" : "=MISMATCH");
                    if (shown == null) shown = m.getAsComponentString();
                    apply(s, null, new ArrayList<>(Collections.nCopies(n, Boolean.FALSE)));
                }
                out.append(" cleared=").append(s.getItemMeta().hasCustomModelDataComponent() ? "NO" : "ok");
                if (aimItems.contains(id)) out.append(" aim=").append(s.hasData(DataComponentTypes.CONSUMABLE) ? "ok" : "MISSING");
                if (shown != null) out.append(" components=").append(shown);
            } catch (RuntimeException ex) {
                out.append(" failed: ").append(ex.getClass().getSimpleName()).append(' ').append(String.valueOf(ex.getMessage()));
                d.plugin().getLogger().warning(out.toString());
                continue;
            }
            d.plugin().getLogger().info(out.toString());
        }
    }
}
`;

