  tests: ["test/cyrus-itemmodel.test.ts (pure: emitted only with states, strict-scan text rules)", "test/cyrus-itemmodel-real.ts (javac 1.21.11 + 26.2, strict scan, Test Flight: enable + self-check log + vanilla component round trip)"],
