const MAX_ASSET_REPAIRS = int(process.env.MB_MAX_ASSET_REPAIRS, 2);
const keptSpecs = new Map(); // build id -> Map(rel -> bytes): texture/sound specs a change build must keep unchanged (plan cannot edit them)
const texOn = (rec) => !!(rec.assets && rec.assets.texture);
const sndOn = (rec) => !!(rec.assets && rec.assets.sound);
const libOn = (rec) => sndOn(rec) && !!rec.assets.library;
// Cyrus R2 data pack studio: the portal's router decided the request is data-driven (and CYRUS_DATAPACK_STUDIO is on).
const DATAPACK_PROMPT_VERSION = "mb-datapack-2026-10-10.1";
const dpOn = (rec) => !!(rec.assets && rec.assets.datapack);
const creOn = (rec) => !!(rec.assets && rec.assets.creature);
/** The BetterModel API jars are installed and verify (deps.json allowlist, sha256). */
const creatureReady = () => { try { IMP.depClasspath(CR.CREATURE_DEPS); return true; } catch { return false; } };
// Cyrus R3 gameplay designers: the portal's router picked the designer route (CYRUS_DESIGNER on). Designs are compiled
// into the workspace sources before validate / precheck / javac / scan.
const DESIGN_PROMPT_VERSION = "mb-design-2026-10-10.1";
const dsOn = (rec) => !!(rec.assets && rec.assets.design);
/** { release, javac } for a Minecraft version: 21 + PATH javac unless the registry says a buildable 25. */
  const f = path.join(ws, "modbuilder.json");
  if (!fs.existsSync(f)) return null;
  try { return JSON.parse(fs.readFileSync(f, "utf8")); } catch { return { _invalid: true }; }
}

