"use strict";
// Item model states in the build service (Cyrus R3). When the portal routes a texture build to item model states
// (assets.itemmodel), the model may write ItemModelSpec v1 files at assets/itemmodels/<name>.json: how one custom item
// looks per display context and which texture it shows in which state (bow pull stages, gun aim / reload). They are
// checked like code with the validator GENERATED from lib/cyrus/itemmodel (./itemmodel-spec.js) against the textures of
// the workspace and the build's exact version; the portal re-validates and EMITS them into the resource pack (the
// service never builds the pack). Plain Node.
const fs = require("fs");
const path = require("path");
const IM = require("./itemmodel-spec");

const ITEMMODEL_DIR = "assets/itemmodels";
const ITEMMODEL_FILE_RE = /^assets\/itemmodels\/[a-z][a-z0-9_]{1,31}\.json$/;
const MAX_ITEMMODEL_FILES = IM.ITEMMODEL_CAPS.maxSpecsPerMod;

function listItemModelFiles(ws) {
  const dir = path.join(ws, ITEMMODEL_DIR);
  let names = [];
  try { names = fs.readdirSync(dir, { withFileTypes: true }); } catch { return []; }
  return names.filter((e) => e.isFile()).map((e) => `${ITEMMODEL_DIR}/${e.name}`).filter((rel) => ITEMMODEL_FILE_RE.test(rel)).sort()
    .map((rel) => ({ rel, abs: path.join(ws, rel), size: fs.statSync(path.join(ws, rel)).size }));
}
function snapshotItemModelSpecs(ws) {
  const out = new Map();
  for (const f of listItemModelFiles(ws)) out.set(f.rel, fs.readFileSync(f.abs));
  return out;
}
const itemModelVersionOk = (mcVersion) => IM.itemModelVersionOk(String(mcVersion)).ok;
/** The texture names the workspace has (assets/textures/<name>.json). */
function textureNamesOf(ws) {
  try { return fs.readdirSync(path.join(ws, "assets/textures")).filter((n) => /^[a-z][a-z0-9_]{1,31}\.json$/.test(n)).map((n) => n.slice(0, -5)).sort(); } catch { return []; }
}

/**
 * Check every item model spec in the workspace (same contract as the other asset checkers):
 *   problems (HARD): invalid JSON / spec, file name != name, unknown texture, more files than allowed; dropped after the
 *   bounded repairs, never shipped. soft: warnings worth one repair round.
 */
function checkWorkspaceItemModels(ws, { mcVersion, textures }) {
  const files = listItemModelFiles(ws);
  const tex = textures || textureNamesOf(ws);
  const results = [];
  const problems = [];
  const soft = [];
  if (files.length > MAX_ITEMMODEL_FILES) problems.push(`${files.length} item model specs; the limit is ${MAX_ITEMMODEL_FILES}.`);
  for (const f of files.slice(0, MAX_ITEMMODEL_FILES)) {
    const want = path.basename(f.rel, ".json");
    const r = { rel: f.rel, name: want, ok: false, problems: [], warnings: [] };
    results.push(r);
    if (f.size > IM.ITEMMODEL_CAPS.maxSpecBytes) { r.problems.push(`${f.rel} is larger than ${IM.ITEMMODEL_CAPS.maxSpecBytes / 1024} KB`); continue; }
    const bytes = fs.readFileSync(f.abs);
    let json;
    try { json = JSON.parse(bytes.toString("utf8")); } catch (e) { r.problems.push(`${f.rel} is not valid JSON: ${String(e.message).slice(0, 160)}`); continue; }
    if (!json || json.name !== want) { r.problems.push(`${f.rel}: "name" is "${json && json.name}" but the file is ${want}.json; they must match (the name is the idle texture's name)`); continue; }
    const v = IM.validateItemModel(json, { textures: tex, version: mcVersion });
    if (!v.ok) { for (const e of v.errors.slice(0, 6)) r.problems.push(`${f.rel}: ${e.path}: ${e.message}`); continue; }
    r.ok = true; r.spec = v.spec; r.needs = v.needs;
    r.sha256 = require("crypto").createHash("sha256").update(bytes).digest("hex");
    r.warnings = v.warnings.map((w) => `${w.path}: ${w.message}`);
    for (const w of r.warnings) soft.push(`${f.rel}: ${w}`);
  }
  for (const r of results) problems.push(...r.problems);
  return { files, results, problems, soft };
}

/** model key (<ns>:<name>) -> { modes, flags, use } of the workspace's valid specs (the designer cross-check and flag indexes). */
function itemModelNeedsOf(ws, namespace, mcVersion) {
  const out = {};
  for (const r of checkWorkspaceItemModels(ws, { mcVersion }).results) if (r.ok) out[`${namespace}:${r.name}`] = { modes: r.needs.modes, flags: r.needs.flags, use: r.needs.use };
  return out;
}

module.exports = { ITEMMODEL_DIR, ITEMMODEL_FILE_RE, MAX_ITEMMODEL_FILES, IM, listItemModelFiles, snapshotItemModelSpecs, itemModelVersionOk, textureNamesOf, checkWorkspaceItemModels, itemModelNeedsOf };

