};

export type SvcTexture = { name: string; path: string; sha256: string; spec: unknown; quality: unknown };
/** Cyrus R1 sound slice: one sound SET (assets/sounds/<key>.json) as the service validated it (spec-level only). */
export type SvcSound = { key: string; path: string; sha256: string; spec: unknown; quality: unknown; events?: { event: string; key: string; role: string; category: string; subtitle: string; variants: number }[] };
/** Cyrus R3: one creature (assets/creatures/<name>.json, a RigSpec) as the service validated it. */
export type SvcCreature = { name: string; path: string; sha256: string; spec: unknown };
export type SvcAssetResult = {
  namespace: string | null; promptVersion: string | null; qualityVersion: string; kept: boolean;
  /** sound slice: kinds kept unchanged because the plan cannot edit them (absent on texture-slice services) */
  keptKinds?: ("texture" | "sound" | "datapack" | "creature" | "design")[];
  textures: SvcTexture[]; sounds?: SvcSound[]; creatures?: SvcCreature[]; downgraded: { name: string; reason: string; kind?: "texture" | "sound" | "datapack" | "creature" | "design" }[]; warnings: string[];
  /** Cyrus R2 data pack studio (services/modbuilder/datapacks.js): the specs as the service validated + emitted them. */
  datapacks?: import("../cyrus/datapack/sync").SvcDatapack[]; datapackPromptVersion?: string | null;
  /** Cyrus R3 gameplay designers (services/modbuilder/designs.js): the designs compiled into the jar + the compile record. */
  designs?: import("../cyrus/designer/sync").SvcDesign[]; designCompile?: { hash?: string; pluginName?: string; configVersion?: number; customHooks?: boolean; modelsApplied?: string[]; compiler?: string; libraryHash?: string } | null; designPromptVersion?: string | null;
};

export async function svcHealth(): Promise<{ ok: boolean; [k: string]: unknown } | null> {
  try {
    const r = await call("/health", { timeoutMs: 4000 });
    return r.ok ? await r.json() : null;
  } catch { return null; }
}

/**
  /** Network/AI capability manifest (service 0.6+, lib/cyrus/capabilities.ts). Absent = offline mod. */
  capabilities?: unknown;
  /** Cyrus R1: custom assets that shipped with this version and their resource pack (lib/cyrus/assets/sync.ts). */
  assets?: MbAssets | null;
  /** Internal: routing + per-AI-call model and cost. Stripped from the customer view (toView). */
  ai?: MbAiInfo | null;
};

/**
 * Custom assets of one build (customer-visible). status:
 *   ready     pack built AND published at its immutable URL; the Pack Loader entry is computed
 *   unhosted  pack built, but pack hosting is off here (CYRUS_PACK_STORE), so it cannot reach players yet
 *   none      the build asked for assets but none passed the checks (see dropped + notices)
 *   failed    the pack could not be built (notices say why); the plugin itself is fine
 */
export type MbAssets = {
  status: "ready" | "unhosted" | "none" | "failed";
  namespace: string;
  projectId: string;
  revisionId: string | null;
  textures: { name: string; model: string; specSha256: string; pngSha256: string; quality: "pass" | "warn" }[];
  /** Cyrus R1 sound slice: one row per shipped sound event; the plugin plays `key` ("<ns>:<set>.<event>"). Absent on old rows. */
  sounds?: { set: string; event: string; key: string; subtitle: string; role: string; category: string; variants: number; quality: "pass" | "warn"; specSha256: string }[];
  /** rendered = in the pack; off = designed but no render host here (not in the pack); failed = the render host failed; none = no sounds */
  soundRender?: "rendered" | "off" | "failed" | "none";
  /**
   * Cyrus R3: animated creatures (RigSpec -> .bbmodel for the Nxeon-managed BetterModel, 26.x only). `spec` is the
   * RigSpec as written; delivery re-compiles it and refuses bytes that differ from bbmodelSha256. Absent on old rows.
   */
  creatures?: { name: string; key: string; specSha256: string; bbmodelSha256: string; pngSha256: string; quality: "pass" | "warn"; bones: number; cubes: number; clips: string[]; sounds: Record<string, string>; spec: unknown }[];
  /** kind absent = texture (rows written before the sound slice) */
  dropped: { name: string; reason: string; kind?: "texture" | "sound" | "datapack" | "creature" | "design" }[];
  /** Cyrus R2 data pack studio: one row per shipped data pack (server-side; rebuilt deterministically from the spec at install). Absent on old rows. */
  datapacks?: { name: string; version: string; specSha256: string; sha256: string; sha1: string; bytes: number; format: { major: number; minor: number }; counts: Record<string, number>; apply: "reload" | "restart" }[];
  /** Cyrus R3 gameplay designers: one row per design item compiled into the jar (re-validated + re-compiled by the portal). Absent on old rows. */
  designs?: { name: string; version: string; specSha256: string; compileHash: string; serviceAgreed: boolean | null; configVersion: number; settings: number; abilities: number }[];
  pack: { sha1: string; sha256: string; bytes: number; format: number; clientVerified: boolean; url: string | null } | null;

