// Cyrus R3 item model states, PORTAL side of a succeeded build: the service's specs are never trusted. Every returned
// ItemModelSpec is validated again against the textures that passed the portal's own texture checks and the build's
// exact version; failures are dropped with a reason (the item keeps its one flat look), the rest go into the pack.
import { createHash } from "node:crypto";
import { canonicalJson } from "../datapack/spec";
import { validateItemModels, type ItemModelSpec, type ItemModelNeeds } from "./spec";

export const ITEMMODEL_SPEC_MIME = "application/vnd.nxeon.item-model+json";
export type SvcItemModelIn = { name?: unknown; spec?: unknown };
export type CheckedItemModel = { name: string; spec: ItemModelSpec; canonical: string; specSha256: string; needs: ItemModelNeeds };

export function checkReturnedItemModels(list: SvcItemModelIn[] | undefined, ctx: { textures: readonly string[]; mcVersion: string }): { ok: CheckedItemModel[]; dropped: { name: string; reason: string }[]; notices: string[] } {
  const out = { ok: [] as CheckedItemModel[], dropped: [] as { name: string; reason: string }[], notices: [] as string[] };
  const all = (list ?? []).slice(0, 12);
  const v = validateItemModels(all.map((x) => x?.spec), { textures: ctx.textures, version: ctx.mcVersion });
  v.results.forEach((r, i) => {
    const name = typeof all[i]?.name === "string" ? String(all[i].name).slice(0, 40) : "?";
    if (!r.ok) { out.dropped.push({ name, reason: r.errors[0] ? `${r.errors[0].path}: ${r.errors[0].message}` : "failed the item model checks" }); out.notices.push(`The item model states of "${name}" were left out: they did not pass Nxeon's checks, so the item keeps one look.`); return; }
    if (r.spec.name !== name || out.ok.some((x) => x.name === name)) { out.dropped.push({ name, reason: "name mismatch or duplicate" }); return; }
    const canonical = canonicalJson(r.spec);
    out.ok.push({ name, spec: r.spec, canonical, specSha256: createHash("sha256").update(canonical).digest("hex"), needs: r.needs });
  });
  return out;
}
