// Cyrus R3 item model states (pure): ItemModelSpec v1 caps and semantic checks, per-category display defaults, the
// vanilla-format reproduction (vanilla bow byte-identical, crossbow by canonical hash + evaluator), emitter golden
// hashes per template and version, packs byte-identical when unused, the designer states (validation, ModelStates only
// when used, compile goldens, strict-scan text rules), TS == generated service JS, artifacts current, the service
// checker + request parser + prompt section, the router, the build request and the portal sync (idempotent).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";
import { DISPLAY_CONTEXTS, ITEMMODEL_CAPS, validateItemModel, validateItemModels, type ItemModelSpec } from "../lib/cyrus/itemmodel/spec";
import { BOW_FULL, CROSSBOW_FULL, GENERATED_FULL, HANDHELD_FULL, categoryDisplay, mergeDisplay } from "../lib/cyrus/itemmodel/display";
import { definitionJson, emitItemModel, evalNode, inputForState, resolveState, stringify, vanillaOrder, type ItemRenderInput } from "../lib/cyrus/itemmodel/emit";
import { bowTemplate, gunTemplate, itemTemplate, staffTemplate, swordTemplate, TEMPLATE_KINDS } from "../lib/cyrus/itemmodel/templates";
import { decideItemStatesRoute, hasItemModels } from "../lib/cyrus/itemmodel/route";
import { checkReturnedItemModels } from "../lib/cyrus/itemmodel/sync";
import { buildPack } from "../lib/cyrus/textures/pack";
import { checkSpec } from "../lib/cyrus/textures/dsl";
import { render } from "../lib/cyrus/textures/render";
import { textureQuality } from "../lib/cyrus/textures/quality";
import { GLOCK } from "../lib/cyrus/textures/sample-glock";
import { FROST_BLADE, HEALTH_POTION } from "../lib/cyrus/textures/sample-items";
import { HANDHELD_DISPLAY } from "../lib/cyrus/textures/display";
import { compileDesigns } from "../lib/cyrus/designer/compile";
import { validateDesign } from "../lib/cyrus/designer/spec";
import { COMPONENTS, libraryHash } from "../lib/cyrus/designer/components";
import { resolveBuildAssets } from "../lib/cyrus/assets/request";
import { syncBuildAssets, type AssetSyncDeps } from "../lib/cyrus/assets/sync";
import { readCyrusMeta } from "../lib/cyrus/meta";
import { indexZip, readEntry } from "../lib/cyrus/inventory/zipread";
import { designAssets, goldenRecord, GOLDEN_NS, stateDesigns } from "../scripts/cyrus/itemmodel-golden";

const ROOT = path.join(__dirname, "..");
const NS = GOLDEN_NS;
const sha = (s: string | Buffer) => createHash("sha256").update(s).digest("hex");
const clone = <T,>(x: T): T => structuredClone(x);
const codes = (r: ReturnType<typeof validateItemModel>) => (r.ok ? [] : r.errors.map((e) => e.code));
const canonical = (v: unknown): string => Array.isArray(v) ? `[${v.map(canonical).join(",")}]` : v && typeof v === "object" ? `{${Object.keys(v).sort().map((k) => `${JSON.stringify(k)}:${canonical((v as Record<string, unknown>)[k])}`).join(",")}}` : JSON.stringify(v);
const zipFiles = (z: Buffer) => { const r = indexZip(z); if (!r.ok) throw new Error("zip"); return Object.fromEntries(r.zip.entries.map((e) => { const x = readEntry(r.zip, e); return [e.name, x.ok ? x.data.toString("utf8") : ""]; })); };
const spec = (extra: Partial<ItemModelSpec> = {}): ItemModelSpec => ({ schemaVersion: 1, name: "probe", category: "tool", ...extra });

// Vanilla facts (verified 2026-10-10 against github.com/InventivetalentDev/minecraft-assets branches 1.21.4, 1.21.11,
// 26.2 and the vanilla client jars; no Mojang file is committed, only these hashes):
//   sha256 of the raw bytes of assets/minecraft/items/bow.json (identical on all three)
const VANILLA_BOW_BYTES = "65ccad786a7bc1cb9b781b2cc134663903e8c266b37d8e4d75fba020ef47ac37";
//   sha256 of the canonical JSON (sorted keys, no spaces, 1.0 -> 1) of items/bow.json and items/crossbow.json
const VANILLA_BOW_CANON = "d85602410f82a56f6709248f8115f1687501e9668558cf6e6ec0919c13685b67";
const VANILLA_CROSSBOW_CANON = { "1.21.4": "2f4d66b33ec259dfd18ab1d5d79ced5f7216414e24fe09d51a66f43a1762c7ef", "1.21.11": "3b776051ca3576e8c94b39df8f73678f2b1d51eebd19826bc48308d6d343741b", "26.2": "3b776051ca3576e8c94b39df8f73678f2b1d51eebd19826bc48308d6d343741b" };
const VANILLA_REF = (item: string) => (id: string) => (id === "idle" ? `minecraft:item/${item}` : `minecraft:item/${item}_${id}`);
const VANILLA_BOW: ItemModelSpec = { schemaVersion: 1, name: "bow", category: "bow", states: [
  { id: "pulling_0", texture: "bow_pulling_0", when: { type: "pull", from: 0 } }, { id: "pulling_1", texture: "bow_pulling_1", when: { type: "pull", from: 0.65 } }, { id: "pulling_2", texture: "bow_pulling_2", when: { type: "pull", from: 0.9 } },
] };
const VANILLA_CROSSBOW: ItemModelSpec = { schemaVersion: 1, name: "crossbow", category: "crossbow", states: [
  { id: "pulling_0", texture: "crossbow_pulling_0", when: { type: "pull", from: 0, source: "crossbow" } }, { id: "pulling_1", texture: "crossbow_pulling_1", when: { type: "pull", from: 0.58, source: "crossbow" } },
  { id: "pulling_2", texture: "crossbow_pulling_2", when: { type: "pull", from: 1, source: "crossbow" } },
  { id: "arrow", texture: "crossbow_arrow", when: { type: "charged", charge: "arrow" } }, { id: "firework", texture: "crossbow_firework", when: { type: "charged", charge: "rocket" } },
] };

describe("ItemModelSpec v1: caps and checks", () => {
  it("templates are valid, their textures pass the texture checks and the quality bar", () => {
    for (const k of TEMPLATE_KINDS) {
      const t = itemTemplate(k);
      const v = validateItemModel(t.spec, { textures: t.textures.map((x) => x.name), version: "1.21.11" });
      assert.ok(v.ok, `${k}: ${JSON.stringify(!v.ok && v.errors)}`);
      for (const tx of t.textures) {
        const c = checkSpec(tx); assert.ok(c.ok, `${tx.name}: ${!c.ok && c.error}`);
        const q = textureQuality(render(tx)); assert.notEqual(q.verdict, "fail", `${tx.name}: ${JSON.stringify(q.checks.filter((x) => x.status === "fail"))}`);
      }
    }
  });
  it("every cap: at the edge accepted, just outside refused", () => {
    const s = (n: number) => spec({ states: Array.from({ length: n }, (_, i) => ({ id: `m${i}`, texture: `t${i}x`, when: { type: "context" as const, contexts: [DISPLAY_CONTEXTS[i % 8]] } })) });
    assert.deepEqual(codes(validateItemModel(spec({ states: Array.from({ length: 8 }, (_, i) => ({ id: `m${i}`, texture: `tx${i}`, when: { type: "mode", value: `v${i}` } })) }))), ["too_many_modes"]);
    assert.deepEqual(codes(validateItemModel(spec({ states: Array.from({ length: 9 }, (_, i) => ({ id: `m${i}`, texture: `tx${i}`, when: { type: "selected" } })) }))), ["schema"]);
    assert.equal(s(1).states!.length, 1);
    const tr = (t: Record<string, unknown>) => validateItemModel(spec({ display: { gui: t } as ItemModelSpec["display"] }));
    assert.ok(tr({ translation: [80, -80, 0], scale: [4, -4, 0], rotation: [360, -360, 0] }).ok);
    for (const bad of [{ translation: [80.1, 0, 0] }, { scale: [4.01, 1, 1] }, { rotation: [0, 361, 0] }, { rotation: [0, 0] }, { size: [1, 1, 1] }]) assert.deepEqual(codes(tr(bad)), ["schema"], JSON.stringify(bad));
    const pull = (from: number) => validateItemModel(spec({ category: "bow", states: [{ id: "p0", texture: "pa", when: { type: "pull", from: 0 } }, { id: "p1", texture: "pb", when: { type: "pull", from } }] }));
    assert.ok(pull(ITEMMODEL_CAPS.pullFrom).ok); assert.deepEqual(codes(pull(100.5)), ["schema"]);
    const dmg = (from: number) => validateItemModel(spec({ states: [{ id: "worn", texture: "pa", when: { type: "damage", from } }] }));
    assert.ok(dmg(1).ok); assert.deepEqual(codes(dmg(0)), ["schema"]); assert.deepEqual(codes(dmg(1.01)), ["schema"]);
    assert.deepEqual(codes(validateItemModel({ ...spec(), extra: 1 })), ["schema"]);
    assert.deepEqual(codes(validateItemModel({ ...spec(), schemaVersion: 2 })), ["schema"]);
    assert.deepEqual(codes(validateItemModel({ ...spec(), name: "Bad Name" })), ["schema"]);
    assert.deepEqual(codes(validateItemModel({ ...spec(), states: [{ id: "x", texture: "y", when: { type: "custom", value: 1 } }] })), ["schema"]);
    assert.deepEqual(codes(validateItemModel({ ...spec(), padding: "x".repeat(17000) })), ["too_big"]);
  });
  it("semantic checks (codes)", () => {
    const S = (states: unknown[], extra: Record<string, unknown> = {}) => codes(validateItemModel(spec({ states: states as ItemModelSpec["states"], ...extra })));
    assert.deepEqual(S([{ id: "idle", texture: "a1", when: { type: "selected" } }]), ["reserved_id"]);
    assert.deepEqual(S([{ id: "a", texture: "a1", when: { type: "selected" } }, { id: "a", texture: "a2", when: { type: "broken" } }]), ["dup_state"]);
    assert.deepEqual(S([{ id: "a", texture: "a1", when: { type: "using" } }, { id: "b", texture: "a2", when: { type: "pull", from: 0 } }], { category: "bow" }), ["using_and_pull"]);
    assert.deepEqual(S([{ id: "b", texture: "a2", when: { type: "pull", from: 0.5 } }], { category: "bow" }), ["pull_no_start"]);
    assert.deepEqual(S([{ id: "a", texture: "a1", when: { type: "pull", from: 0 } }, { id: "b", texture: "a2", when: { type: "pull", from: 0.5, source: "crossbow" } }], { category: "crossbow" }), ["pull_mixed"]);
    assert.deepEqual(S([{ id: "a", texture: "a1", when: { type: "pull", from: 0, source: "crossbow" } }], { category: "bow" }), ["crossbow_only"]);
    assert.deepEqual(S([{ id: "a", texture: "a1", when: { type: "charged", charge: "arrow" } }]), ["crossbow_only"]);
    assert.deepEqual(S([{ id: "a", texture: "a1", when: { type: "mode", value: "x" } }, { id: "b", texture: "a2", when: { type: "mode", value: "x" } }]), ["dup_mode"]);
    assert.deepEqual(S(Array.from({ length: 5 }, (_, i) => ({ id: `f${i}`, texture: `a${i}x`, when: { type: "flag", name: `f${i}` } }))), ["too_many_flags"]);
    assert.deepEqual(S([{ id: "a", texture: "a1", when: { type: "context", contexts: ["gui", "head"] } }, { id: "b", texture: "a2", when: { type: "context", contexts: ["head"] } }]), ["context_overlap"]);
    assert.deepEqual(S([{ id: "a", texture: "a1", when: { type: "context", contexts: DISPLAY_CONTEXTS.slice(0, 7) } }, { id: "b", texture: "a2", when: { type: "context", contexts: ["thirdperson_lefthand"] } }]), ["context_all"]);
    assert.deepEqual(S([{ id: "a", texture: "a1", when: { type: "selected" } }, { id: "b", texture: "a2", when: { type: "selected" } }]), ["dup_selected"]);
    assert.deepEqual(codes(validateItemModel(spec({ states: [{ id: "a", texture: "nope", when: { type: "broken" } }] }), { textures: ["probe"] })), ["texture_unknown"]);
    assert.deepEqual(codes(validateItemModel(spec(), { version: "1.21.1" })), ["version"]);
    assert.ok(validateItemModel(spec(), { version: "26.2" }).ok);
    const w = validateItemModel(spec({ category: "flat", states: [{ id: "a", texture: "a1", when: { type: "using" } }] }));
    assert.ok(w.ok && w.warnings.some((x) => x.code === "use_needs_usable_base"));
    const m = validateItemModels([spec(), spec()]);
    assert.ok(!m.ok && m.errors.some((e) => e.code === "dup_name"));
    assert.ok(!validateItemModels(Array.from({ length: 13 }, (_, i) => spec({ name: `p${i}x` }))).ok);
  });
  it("needs: modes, flags (index = declaration order), use, textures", () => {
    const v = validateItemModel(spec({ category: "gun", states: [{ id: "r", texture: "a1", when: { type: "mode", value: "reloading" } }, { id: "e", texture: "a2", when: { type: "flag", name: "empty" } }, { id: "h", texture: "a3", when: { type: "flag", name: "hot" } }, { id: "aim", texture: "a1", when: { type: "using" } }] }));
    assert.ok(v.ok);
    assert.deepEqual(v.needs, { modes: ["reloading"], flags: ["empty", "hot"], use: true, textures: ["probe", "a1", "a2", "a3"] });
  });
});

describe("display: per-category defaults = vanilla", () => {
  it("bow / crossbow / handheld / generated are vanilla's numbers in all 8 contexts", () => {
    assert.deepEqual(categoryDisplay("bow"), BOW_FULL);
    assert.deepEqual(BOW_FULL.thirdperson_righthand, { rotation: [-80, 260, -40], translation: [-1, -2, 2.5], scale: [0.9, 0.9, 0.9] });
    assert.deepEqual(BOW_FULL.thirdperson_lefthand.rotation, [-80, -280, 40]);
    assert.deepEqual(CROSSBOW_FULL.firstperson_righthand, { rotation: [-90, 0, -55], translation: [1.13, 3.2, 1.13], scale: [0.68, 0.68, 0.68] });
    assert.deepEqual(categoryDisplay("sword"), HANDHELD_FULL);
    assert.deepEqual(categoryDisplay("wand"), HANDHELD_FULL);
    for (const v of ["firstperson_righthand", "thirdperson_righthand", "firstperson_lefthand", "thirdperson_lefthand"] as const) assert.deepEqual(HANDHELD_FULL[v], HANDHELD_DISPLAY[v], "the pack's existing handheld values");
    assert.deepEqual(categoryDisplay("flat"), GENERATED_FULL);
    assert.deepEqual(GENERATED_FULL.ground, { rotation: [0, 0, 0], translation: [0, 2, 0], scale: [0.5, 0.5, 0.5] });
    assert.deepEqual(GENERATED_FULL.head, { rotation: [0, 180, 0], translation: [0, 13, 7], scale: [1, 1, 1] });
    assert.deepEqual(GENERATED_FULL.fixed, { rotation: [0, 180, 0], translation: [0, 0, 0], scale: [1, 1, 1] });
    assert.deepEqual(GENERATED_FULL.gui, { rotation: [0, 0, 0], translation: [0, 0, 0], scale: [1, 1, 1] }, "vanilla generated has no gui transform (identity)");
    assert.deepEqual(GENERATED_FULL.thirdperson_lefthand, GENERATED_FULL.thirdperson_righthand, "a missing left hand takes the right hand's");
    for (const d of [BOW_FULL, CROSSBOW_FULL, HANDHELD_FULL]) for (const c of ["gui", "ground", "fixed", "head"] as const) assert.deepEqual(d[c], GENERATED_FULL[c]);
  });
  it("gun: re-gripped handgun hands from the idle pixels; overrides merge per context and field and are capped", () => {
    const g = gunTemplate();
    const d = categoryDisplay("gun", render(g.textures[0]), g.spec.name);
    assert.notDeepEqual(d.firstperson_righthand, HANDHELD_FULL.firstperson_righthand);
    assert.deepEqual(d.firstperson_righthand.rotation, [-10, 150, 30]);
    assert.deepEqual(categoryDisplay("gun"), HANDHELD_FULL, "no raster: the tool grip");
    const m = mergeDisplay(GENERATED_FULL, { gui: { scale: [2, 2, 2] } }, { gui: { rotation: [10, 0, 0] }, head: { translation: [0, 99, -0.00001] } });
    assert.deepEqual(m.gui, { rotation: [10, 0, 0], translation: [0, 0, 0], scale: [2, 2, 2] });
    assert.deepEqual(m.head.translation, [0, 80, 0], "capped at 80, no -0");
    assert.deepEqual(m.ground, GENERATED_FULL.ground);
  });
});

describe("vanilla format reproduction", () => {
  it("vanilla bow: BYTE-identical items/bow.json (1.21.4, 1.21.11, 26.2 ship the same file)", () => {
    const text = stringify(definitionJson(VANILLA_BOW, VANILLA_REF("bow")));
    assert.equal(sha(text), VANILLA_BOW_BYTES);
    assert.equal(sha(canonical(JSON.parse(text))), VANILLA_BOW_CANON);
    // exact property names and thresholds as verified
    const n = JSON.parse(text).model;
    assert.equal(n.type, "minecraft:condition"); assert.equal(n.property, "minecraft:using_item");
    assert.equal(n.on_true.type, "minecraft:range_dispatch"); assert.equal(n.on_true.property, "minecraft:use_duration"); assert.equal(n.on_true.scale, 0.05);
    assert.deepEqual(n.on_true.entries.map((e: { threshold: number }) => e.threshold), [0.65, 0.9]);
  });
  it("vanilla crossbow: 1.21.11 / 26.2 structure equal by canonical hash; 1.21.4 = the two outer layers swapped", () => {
    const ours = definitionJson(VANILLA_CROSSBOW, VANILLA_REF("crossbow")) as { model: Record<string, unknown> };
    assert.equal(sha(canonical(ours)), VANILLA_CROSSBOW_CANON["1.21.11"]);
    assert.equal(VANILLA_CROSSBOW_CANON["26.2"], VANILLA_CROSSBOW_CANON["1.21.11"]);
    // 1.21.4: condition(using_item){on_true: range, on_false: select(charge_type){cases, fallback: idle}}
    const sel = ours.model as { cases: unknown; fallback: { on_true: unknown; on_false: unknown; property: string; type: string }; property: string; type: string };
    const old = { model: { type: sel.fallback.type, property: sel.fallback.property, on_true: sel.fallback.on_true, on_false: { type: sel.type, property: sel.property, cases: sel.cases, fallback: sel.fallback.on_false } } };
    assert.equal(sha(canonical(old)), VANILLA_CROSSBOW_CANON["1.21.4"]);
    // same model for every reachable input (a charged crossbow is never "used": using one fires it)
    for (const using of [false, true]) for (const charge of [null, "arrow", "rocket"] as const) for (const pull of [0, 0.3, 0.58, 0.9, 1, 1.5]) {
      if (using && charge) continue;
      const i: ItemRenderInput = { using, charge, crossbowPull: pull };
      assert.equal(evalNode(ours.model, i), evalNode(old.model, i), JSON.stringify(i));
    }
    assert.equal(evalNode(ours.model, { using: true, crossbowPull: 0.6 }), "minecraft:item/crossbow_pulling_1");
    assert.equal(evalNode(ours.model, { charge: "rocket" }), "minecraft:item/crossbow_firework");
  });
  it("evaluator: bow pull stages at vanilla's thresholds (ticks of use x 0.05)", () => {
    const n = (definitionJson(VANILLA_BOW, VANILLA_REF("bow")) as { model: unknown }).model;
    const at = (using: boolean, ticks: number) => evalNode(n, { using, useTicks: ticks });
    assert.equal(at(false, 30), "minecraft:item/bow");
    assert.equal(at(true, 0), "minecraft:item/bow_pulling_0");
    assert.equal(at(true, 12), "minecraft:item/bow_pulling_0");
    assert.equal(at(true, 13), "minecraft:item/bow_pulling_1", "13 x 0.05 = 0.65");
    assert.equal(at(true, 17), "minecraft:item/bow_pulling_1");
    assert.equal(at(true, 18), "minecraft:item/bow_pulling_2", "18 x 0.05 = 0.9");
  });
  it("layer order: broken > damage > mode > flag > charged > using > selected > context > idle", () => {
    const s = spec({ category: "gun", states: [
      { id: "ctx", texture: "t1", when: { type: "context", contexts: ["gui"] } }, { id: "sel", texture: "t2", when: { type: "selected" } }, { id: "aim", texture: "t3", when: { type: "using" } },
      { id: "hot", texture: "t4", when: { type: "flag", name: "hot" } }, { id: "rel", texture: "t5", when: { type: "mode", value: "reloading" } }, { id: "worn", texture: "t6", when: { type: "damage", from: 0.5 } }, { id: "brk", texture: "t7", when: { type: "broken" } },
    ] });
    const all: ItemRenderInput = { context: "gui", selected: true, using: true, flags: [true], strings: ["reloading"], damage: 0.6, broken: true };
    assert.equal(resolveState(s, all), "brk");
    assert.equal(resolveState(s, { ...all, broken: false }), "worn");
    assert.equal(resolveState(s, { ...all, broken: false, damage: 0.4 }), "rel");
    assert.equal(resolveState(s, { ...all, broken: false, damage: 0, strings: [] }), "hot");
    assert.equal(resolveState(s, { ...all, broken: false, damage: 0, strings: [], flags: [false] }), "aim");
    assert.equal(resolveState(s, { context: "gui", selected: true }), "sel");
    assert.equal(resolveState(s, { context: "gui" }), "ctx");
    assert.equal(resolveState(s, { context: "head" }), "idle");
    for (const st of s.states!) assert.equal(resolveState(s, inputForState(s, st.id, "firstperson_righthand")), st.id, `scrubber input for ${st.id}`);
  });
});

