describe("designer: item model states", () => {
  const ctx = (version = "1.21.11") => ({ version, namespace: NS, pluginName: "StateArsenal", assets: designAssets() });
  it("the three stateful designs are valid; state rules are checked", () => {
    for (const d of stateDesigns()) { const v = validateDesign(d, { version: "1.21.11", namespace: NS, items: [d.id], assets: designAssets() }); assert.ok(v.ok, `${d.id}: ${JSON.stringify(v.errors)}`); assert.deepEqual(v.warnings.filter((w) => w.code.startsWith("state")), []); }
    const pistol = stateDesigns()[0];
    const V = (mut: (d: typeof pistol) => void) => { const d = clone(pistol); mut(d); const v = validateDesign(d, { version: "1.21.11", namespace: NS, items: [d.id], assets: designAssets() }); return { errors: v.errors.map((e) => e.code), warnings: v.warnings.map((w) => w.code) }; };
    assert.deepEqual(V((d) => { d.states.modes[0].ability = "nope"; }).errors, ["unresolved_ref"]);
    assert.deepEqual(V((d) => { d.states.modes[0].during = "no_charges"; }).errors, ["state_no_charges"]);
    assert.deepEqual(V((d) => { d.states.modes[0].during = "charging"; }).errors, ["state_not_charge"]);
    assert.deepEqual(V((d) => { d.states.modes.push({ ...d.states.modes[0] }); }).errors, ["dup_state"]);
    assert.deepEqual(V((d) => { d.base = "minecraft:bow"; }).errors, ["aim_base"]);
    assert.deepEqual(V((d) => { d.base = "minecraft:bread"; }).errors, ["aim_base"]);
    assert.ok(V((d) => { d.states.modes[0].value = "empty"; }).warnings.includes("state_unmapped"));
    assert.ok(V((d) => { delete (d as { assets?: unknown }).assets; }).warnings.includes("states_without_model"));
    assert.deepEqual(V((d) => { (d.states as Record<string, unknown>).extra = 1; }).errors, ["schema"]);
    const old = validateDesign(pistol, { version: "1.21.1", namespace: NS, items: [pistol.id] });
    assert.ok(old.ok && old.warnings.some((w) => w.code === "states_unsupported"));
  });
  it("ModelStates is emitted only with states on 1.21.4+; existing designs unchanged (library hash, no ModelStates)", () => {
    for (const v of ["1.21.4", "1.21.11", "26.2"]) {
      const r = compileDesigns(stateDesigns(), ctx(v)); assert.ok(r.ok, JSON.stringify(!r.ok && r.errors));
      const ms = r.files.find((f) => f.path.endsWith("designer/ModelStates.java"));
      assert.ok(ms && ms.role === "component");
      const main = r.files.find((f) => f.path.endsWith("/StateArsenal.java"))!.content;
      assert.match(main, /new ModelStates\.Rule\("service_pistol", "reload", ModelStates\.During\.COOLDOWN, "reloading", -1\)/);
      assert.match(main, /new ModelStates\.Rule\("storm_rod", "surge", ModelStates\.During\.CHARGING, "charging", -1\)/);
      assert.match(main, /Map\.of\("service_pistol", 0, "storm_rod", 0\), Set\.of\("service_pistol"\)\);/);
      assert.match(main, /modelStates\.stop\(\);/);
      const pistol = r.files.find((f) => f.path.endsWith("items/ServicePistolItem.java"))!.content;
      assert.match(pistol, /ModelStates\.aimable\(s, ItemUseAnimation\.BOW\);\n        return s;/);
      const bow = r.files.find((f) => f.path.endsWith("items/HunterBowItem.java"))!.content;
      assert.doesNotMatch(bow, /ModelStates|ItemUseAnimation/);
      assert.ok(r.notes.some((n) => /Service Pistol changes its look in hand: "reloading" while reload cools down/.test(n)));
      assert.ok(r.notes.some((n) => /hold right-click to aim/.test(n)));
    }
    const legacy = compileDesigns(stateDesigns(), ctx("1.21.1"));
    assert.ok(legacy.ok && !legacy.files.some((f) => /ModelStates|ItemUseAnimation/.test(f.content)));
    assert.ok(legacy.notes.some((n) => /item model states need Minecraft 1\.21\.4/.test(n)));
    assert.equal(COMPONENTS.length, 17); assert.ok(!COMPONENTS.some((c) => c.file.includes("ModelStates")));
    assert.match(libraryHash(), /^[0-9a-f]{64}$/);
    const plain = compileDesigns([stateDesigns()[1]], ctx());
    assert.ok(plain.ok && !plain.files.some((f) => f.path.endsWith("ModelStates.java")), "a bow with no states: no component");
  });
  it("flag indexes follow the item model spec's order, not the design's", () => {
    const d = clone(stateDesigns()[0]) as Record<string, any>;
    d.states = { flags: [{ name: "hot", ability: "fire", during: "cooldown" }, { name: "empty", ability: "fire", during: "no_charges" }] };
    const r = compileDesigns([d], { version: "1.21.11", namespace: NS, pluginName: "StateArsenal", assets: { models: [`${NS}:service_pistol`], itemModels: { [`${NS}:service_pistol`]: { modes: [], flags: ["empty", "hot"], use: true } } } });
    assert.ok(r.ok);
    const main = r.files.find((f) => f.path.endsWith("/StateArsenal.java"))!.content;
    assert.match(main, /"fire", ModelStates\.During\.COOLDOWN, null, 1\)/); assert.match(main, /"fire", ModelStates\.During\.NO_CHARGES, null, 0\)/);
    assert.match(main, /Map\.of\("service_pistol", 2\)/);
  });
  it("generated state code: no reflection / threads / network / commands; only the documented event cancel", () => {
    const r = compileDesigns(stateDesigns(), ctx()); assert.ok(r.ok);
    const java = r.files.filter((f) => f.path.endsWith(".java")).map((f) => f.content).join("\n");
    for (const bad of [/java\.lang\.reflect|Class\.forName|getDeclared/, /new Thread|Executor|CompletableFuture|runTaskAsynchronously|runTaskTimerAsynchronously/, /java\.net|HttpClient|Socket/, /dispatchCommand|ProcessBuilder|Runtime\.getRuntime/]) assert.doesNotMatch(java, bad);
    const ms = r.files.find((f) => f.path.endsWith("ModelStates.java"))!.content;
    assert.equal((ms.match(/setCancelled\(true\)/g) ?? []).length, 1);
    assert.match(ms, /aimItems\.contains\(id\)\) e\.setCancelled\(true\)/);
  });
});

