// REAL item-model-states runs ON node-2 (not part of the unit suite: real javac, real strict scan, real Paper boots).
//   scripts/devhost run --lock -- npx tsx test/cyrus-itemmodel-real.ts --out /tank/nxeon-build/tmp/cyrus-r10-itemstates/results.json
// No real Minecraft client, no bot, no AI model: how the item LOOKS and switches in a client is NOT exercised here.
// Per lane (1.21.11 on JDK 21, 26.2 on JDK 25, each against the resolved Paper classpath):
//   1. the three stateful test designs (gun with aim + reloading mode, bow, staff with charging mode) compiled by the TS
//      compiler -> javac --release N -proc:none -Xlint:deprecation,removal; reproducible jar; strict scan (bytecode + source)
//   2. the pack for the same mod (gun/bow/staff templates) built and its definition files checked against the spec
//   3. Test Flight: plugin enabled, items listed (identity, material), ModelStates' enable self-check in the log (each
//      state set on a real ItemStack the plugin built, read back, cleared; the aim consumable present; the vanilla
//      component string the stack carries), then a VANILLA round trip of the same components through RCON
//      (item replace + data get on a chest), no ERROR lines from the plugin
import { execFileSync, spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { compileDesigns, type CompileOk } from "../lib/cyrus/designer/compile";
import { buildPack } from "../lib/cyrus/textures/pack";
import { itemTemplate } from "../lib/cyrus/itemmodel/templates";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { describe as describeSummary } from "../lib/cyrus/testflight/summary";
import type { RconCheck } from "../lib/cyrus/testflight/types";
import { indexZip, readEntry } from "../lib/cyrus/inventory/zipread";
import { designAssets, GOLDEN_NS, stateDesigns } from "../scripts/cyrus/itemmodel-golden";

const ROOT = path.resolve(__dirname, "..");
const T = "/tank/nxeon-build/tmp";
const TF = `${T}/testflight`;
const RUN = `${T}/cyrus-r10-itemstates/run-${Date.now().toString(36)}`;
const NS = GOLDEN_NS;
const PLUGIN = "StateArsenal";
const LANES = [
  { version: "1.21.11", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.11.txt` },
  { version: "26.2", jdk: `${TF}/jdk/25`, release: "25", cp: `${T}/r0-26x/classpath/26.2.txt` },
];
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const walk = (dir: string, out: string[] = []): string[] => { for (const e of readdirSync(dir, { withFileTypes: true })) { const p = path.join(dir, e.name); if (e.isDirectory()) walk(p, out); else out.push(p); } return out; };

const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
async function fly(spec: Parameters<typeof runTestFlight>[0], label: string) {
  for (let attempt = 1, wait = 15000; attempt <= 14; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: localRemote });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}

function build(r: CompileOk, lane: (typeof LANES)[number]) {
  const dir = path.join(RUN, lane.version);
  rmSync(dir, { recursive: true, force: true });
  for (const f of r.files) { const abs = path.join(dir, "ws", f.path); mkdirSync(path.dirname(abs), { recursive: true }); writeFileSync(abs, f.content); }
  const classes = path.join(dir, "classes");
  mkdirSync(classes, { recursive: true });
  const sources = walk(path.join(dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).sort();
  const cp = readFileSync(lane.cp, "utf8").replace(/\n/g, "").trim();
  let javacOut = "";
  try { javacOut = execFileSync(`${lane.jdk}/bin/javac`, ["-J-Xmx768m", "--release", lane.release, "-proc:none", "-encoding", "UTF-8", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...sources], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }); }
  catch (e) { const x = e as { stdout?: string; stderr?: string }; throw new Error(`javac failed on ${lane.version}:\n${(x.stderr ?? "") + (x.stdout ?? "")}`.slice(0, 6000)); }
  for (const f of ["plugin.yml", "config.yml"]) writeFileSync(path.join(classes, f), readFileSync(path.join(dir, "ws/src/main/resources", f)));
  const entries = walk(classes).map((f) => path.relative(classes, f)).sort();
  const jar = (out: string) => { execFileSync(`${lane.jdk}/bin/jar`, ["--create", "--file", out, "--date", "2026-01-01T00:00:00Z", ...entries.flatMap((e) => ["-C", classes, e])]); return sha(readFileSync(out)); };
  const jarPath = path.join(dir, `${PLUGIN}-${lane.version}.jar`);
  const h1 = jar(jarPath), h2 = jar(path.join(dir, "again.jar"));
  return { dir, classes, sources: sources.length, classFiles: entries.filter((e) => e.endsWith(".class")).length, javacWarnings: (javacOut.match(/warning:/g) ?? []).length, javacOut: javacOut.slice(0, 2000), jarPath, jarSha256: h1, reproducible: h1 === h2 };
}

function scan(b: ReturnType<typeof build>, lane: (typeof LANES)[number]) {
  const S = require(path.join(ROOT, "services/modbuilder/scan.js"));
  const oldPath = process.env.PATH;
  process.env.PATH = `${lane.jdk}/bin:${oldPath}`;
  try {
    const bytecode = S.scanBytecode(b.classes, { profile: "strict" });
    const src = walk(path.join(b.dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).map((abs) => ({ abs, rel: path.relative(path.join(b.dir, "ws"), abs) }));
    const all = [...bytecode, ...S.scanSource(src, { profile: "strict" })];
    return { blocks: all.filter((f: { severity: string }) => f.severity === "block").length, warnings: all.filter((f: { severity: string }) => f.severity === "warn").length, findings: all.map((f: { severity: string; rule: string; where: string }) => `${f.severity}:${f.rule}@${f.where}`) };
  } finally { process.env.PATH = oldPath; }
}

function harvest(runId: string | null) {
  const out: Record<string, unknown> = {};
  if (!runId || !/^[A-Za-z0-9_-]+$/.test(runId)) return out;
  const dir = path.join(TF, "runs", runId);
  const log = path.join(dir, "logs/latest.log");
  const lines = existsSync(log) ? readFileSync(log, "utf8").split("\n") : [];
  out.selfCheck = lines.filter((l) => /model states [a-z_]+:/.test(l)).map((l) => l.replace(/^.*?model states /, "model states ").slice(0, 600));
  out.pluginLog = lines.filter((l) => /StateArsenal/.test(l) && !/Preparing/.test(l)).map((l) => l.slice(0, 300)).slice(0, 20);
  out.pluginErrorLines = lines.filter((l) => /\/(ERROR|FATAL)\]|Exception/.test(l) && /StateArsenal|statearsenal|ModelStates/.test(l)).map((l) => l.slice(0, 300)).slice(0, 20);
  out.sandboxNoiseLines = lines.filter((l) => /\/(ERROR|FATAL)\]/.test(l) && !/StateArsenal|statearsenal/.test(l)).length;
  rmSync(dir, { recursive: true, force: true });
  return out;
}

function packCheck(version: string) {
  const t = [itemTemplate("gun", "service_pistol"), itemTemplate("bow", "hunter_bow"), itemTemplate("staff", "storm_rod")];
  const p = buildPack({ namespace: NS, description: `${PLUGIN}: custom textures by Cyrus`, mcVersion: version, textures: t.flatMap((x) => x.textures), itemModels: t.map((x) => x.spec), allowPreview: true });
  if (!p.ok) return { ok: false, error: p.error };
  const z = indexZip(p.pack.zip);
  const files = z.ok ? z.zip.entries.map((e) => e.name) : [];
  const def = (n: string) => { if (!z.ok) return null; const e = z.zip.entries.find((x) => x.name === `assets/${NS}/items/${n}.json`); const r = e ? readEntry(z.zip, e) : null; return r && r.ok ? JSON.parse(r.data.toString("utf8")) : null; };
  return { ok: true, sha1: p.pack.sha1, format: p.pack.packFormat, files: files.length, itemModels: p.pack.itemModels!.map((x) => ({ name: x.name, states: x.states.map((s) => s.id), modes: x.needs.modes })), pistolTop: def("service_pistol")?.model?.property, bowTop: def("hunter_bow")?.model?.property, swapBob: def("service_pistol")?.hand_animation_on_swap };
}

async function main() {
  const oi = process.argv.indexOf("--out");
  const res: Record<string, unknown> = { at: new Date().toISOString(), host: "node-2", realClient: false, bot: false, aiModel: "none (designs are fixtures)", lanes: [] as unknown[] };
  mkdirSync(RUN, { recursive: true });
  for (const lane of LANES) {
    const L: Record<string, unknown> = { version: lane.version, jdk: lane.release };
    (res.lanes as unknown[]).push(L);
    const c = compileDesigns(stateDesigns(), { version: lane.version, namespace: NS, pluginName: PLUGIN, assets: designAssets() });
    if (!c.ok) { L.compile = { ok: false, errors: c.errors }; continue; }
    L.compile = { ok: true, hash: c.hash, files: c.files.length, modelStates: c.files.some((f) => f.path.endsWith("ModelStates.java")) };
    const b = build(c, lane);
    L.javac = { ok: true, sources: b.sources, classFiles: b.classFiles, warnings: b.javacWarnings, output: b.javacOut };
    L.jar = { sha256: b.jarSha256, reproducible: b.reproducible };
    L.scan = scan(b, lane);
    L.pack = packCheck(lane.version);
    console.log(`${lane.version}: javac ok (${b.sources} sources, ${b.javacWarnings} warnings), reproducible=${b.reproducible}, scan blocks=${(L.scan as { blocks: number }).blocks}`);
    const X = 0, Y = 100, Z = 0;
    const pistol = `minecraft:iron_horse_armor[minecraft:item_model="${NS}:service_pistol",minecraft:custom_model_data={strings:["reloading"]},minecraft:consumable={consume_seconds:3600f,animation:"bow",sound:"minecraft:intentionally_empty",has_consume_particles:false}]`;
    const rcon: RconCheck[] = [
      { id: "plugins", command: "plugins", expect: [PLUGIN] },
      { id: "list-identity", command: "statearsenal list", expect: ["service_pistol: identity=ok material=iron_horse_armor", "hunter_bow: identity=ok material=bow", "storm_rod: identity=ok material=blaze_rod"], expectNot: ["MISSING", "internal error", "Exception"] },
      { id: "give-unknown", command: "statearsenal give excalibur Nobody", expect: ["Unknown item excalibur"] },
      { id: "forceload", command: `forceload add ${X} ${Z}` },
      { id: "chest", command: `setblock ${X} ${Y} ${Z} minecraft:chest` },
      { id: "vanilla-components-in", command: `item replace block ${X} ${Y} ${Z} container.0 with ${pistol}`, expectNot: ["Unknown", "Expected", "Malformed", "Invalid"] },
