    L.flight = { status: f.report.status, overall: f.summary.overall, success: f.summary.success, line: describeSummary(f.summary), bootMs: f.report.bootMs, peakRssMb: f.report.peakRssKb ? Math.round(f.report.peakRssKb / 1024) : null, paper: f.report.engine?.paper ?? null, jdkVersion: f.report.engine?.jdk.version ?? null, checks: f.report.checks.map((x) => ({ id: x.id, status: x.status, evidence: x.evidence.slice(0, 16) })), disk: harvest(f.report.runId ?? null) };
    const sc = ((L.flight as { disk: { selfCheck?: string[] } }).disk.selfCheck ?? []);
    L.selfCheckOk = sc.length === 2 && sc.every((l) => /=ok/.test(l) && /cleared=ok/.test(l) && !/MISMATCH|MISSING|failed|cleared=NO/.test(l)) && sc.some((l) => /service_pistol: mode reloading=ok cleared=ok aim=ok components=/.test(l));
