  if (w.type === "pull") { const i = all.filter((x) => x.when.type === "pull").sort((a, b) => (a.when as { from: number }).from - (b.when as { from: number }).from).indexOf(st); return `Pull ${i + 1}`; }
  if (w.type === "using") return "Use";
  if (w.type === "mode") return cap(w.value);
  if (w.type === "flag") return cap(w.name);
  if (w.type === "charged") return w.charge === "arrow" ? "Loaded" : "Rocket";
  return cap(st.id);
}

/** The item model a texture belongs to (as idle or as a state texture), else the pack's default for it. */
export function previewModel(cur: string, specs: readonly ItemModelSpec[]): PreviewModel {
  const spec = specs.find((s) => s.name === cur) ?? specs.find((s) => (s.states ?? []).some((x) => x.texture === cur));
  if (!spec) return { spec: { schemaVersion: 1, name: cur, category: gripKindOf(cur) === "handgun" ? "gun" : "tool" }, derived: true, states: [{ id: "idle", label: "Idle", texture: cur }] };
  const st = spec.states ?? [];
  return { spec, derived: false, states: [{ id: "idle", label: "Idle", texture: spec.name }, ...st.map((s) => ({ id: s.id, label: stateLabel(s, st), texture: s.texture }))] };
}

/** The display of every state of the model (needs the idle raster for the gun grip). */
export const previewDisplays = (m: PreviewModel, idle?: Raster): Record<string, FullDisplay> => stateDisplays(m.spec, idle);

export const ARM = { skin: "#6152b8", skinTop: "#8676dc", skinSide: "#4a3e94", edge: "#120d26", slot: "#8b8b8b", slotHi: "#ffffff", slotLo: "#373737", slotIn: "#8b8b8b", frame: "#8a5a32", frameIn: "#b38a5e", shadow: "#000000" };

const rad = (d: number) => (d * Math.PI) / 180;
const shade = (hex: string, k: number) => "#" + [1, 3, 5].map((i) => Math.max(0, Math.min(255, Math.round(parseInt(hex.slice(i, i + 2), 16) * k))).toString(16).padStart(2, "0")).join("");
const hexOf = (p: Uint8ClampedArray, o: number) => "#" + [p[o], p[o + 1], p[o + 2]].map((v) => v.toString(16).padStart(2, "0")).join("");

type Q = { w: Vec3[]; fill: string; part: Poly["part"]; bias: number; stroke?: string; screen?: boolean };

/** The extruded item (one slab per opaque texel: both faces + open edges), in context space (1/16 block, y up). */
function itemQuads(r: Raster, place: (v: Vec3) => Vec3): Q[] {
  const n = r.size, k = 16 / n, out: Q[] = [];
  const op = (x: number, y: number) => x >= 0 && y >= 0 && x < n && y < n && r.px[(y * n + x) * 4 + 3] > 0;
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    if (!op(x, y)) continue;
    const col = hexOf(r.px, (y * n + x) * 4);
    const x0 = x * k, x1 = (x + 1) * k, y0 = 16 - (y + 1) * k, y1 = 16 - y * k;
    const V = (a: number, b: number, z: number) => place([a, b, z]);
    out.push({ w: [V(x0, y0, 8.5), V(x1, y0, 8.5), V(x1, y1, 8.5), V(x0, y1, 8.5)], fill: col, part: "item", bias: 0 });
    out.push({ w: [V(x0, y0, 7.5), V(x0, y1, 7.5), V(x1, y1, 7.5), V(x1, y0, 7.5)], fill: shade(col, 0.62), part: "item", bias: 0 });
    if (!op(x, y - 1)) out.push({ w: [V(x0, y1, 7.5), V(x0, y1, 8.5), V(x1, y1, 8.5), V(x1, y1, 7.5)], fill: shade(col, 0.92), part: "item", bias: 0 });
    if (!op(x, y + 1)) out.push({ w: [V(x0, y0, 7.5), V(x1, y0, 7.5), V(x1, y0, 8.5), V(x0, y0, 8.5)], fill: shade(col, 0.55), part: "item", bias: 0 });
    if (!op(x - 1, y)) out.push({ w: [V(x0, y0, 7.5), V(x0, y0, 8.5), V(x0, y1, 8.5), V(x0, y1, 7.5)], fill: shade(col, 0.78), part: "item", bias: 0 });
    if (!op(x + 1, y)) out.push({ w: [V(x1, y0, 7.5), V(x1, y1, 7.5), V(x1, y1, 8.5), V(x1, y0, 8.5)], fill: shade(col, 0.68), part: "item", bias: 0 });
  }
  return out;
}

const box = (c: Vec3, s: Vec3, fills: { top: string; side: string; front: string }): Q[] => {
  const [x0, y0, z0] = [c[0] - s[0] / 2, c[1] - s[1] / 2, c[2] - s[2] / 2], [x1, y1, z1] = [c[0] + s[0] / 2, c[1] + s[1] / 2, c[2] + s[2] / 2];
  return [
    { w: [[x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1]], fill: fills.top, part: "arm", bias: 0, stroke: ARM.edge },
    { w: [[x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]], fill: fills.front, part: "arm", bias: 0, stroke: ARM.edge },
    { w: [[x0, y0, z0], [x0, y0, z1], [x0, y1, z1], [x0, y1, z0]], fill: fills.side, part: "arm", bias: 0, stroke: ARM.edge },
    { w: [[x1, y0, z0], [x1, y1, z0], [x1, y1, z1], [x1, y0, z1]], fill: fills.side, part: "arm", bias: 0, stroke: ARM.edge },
    { w: [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0]], fill: fills.front, part: "arm", bias: 0, stroke: ARM.edge },
  ];
};

/**
 * One context view as depth-sorted canvas polygons. `t` = the context's display transform. First / third person reuse
 * the studio's "In hand" scene (glove and sleeve included) with this transform.
 */
export function contextScene(r: Raster, name: string, ctx: PreviewContext, t: DisplayTransform, W: number, H: number, gun = false): { polys: Poly[] } {
  if (ctx === "firstperson" || ctx === "thirdperson") return { polys: heldScene(r, name, ctx, W, H, t, gun ? "handgun" : "tool").polys };
  // camera: yaw (around y) then pitch (around x), orthographic; z toward the camera
  const cam = { gui: [0, 0], ground: [-35, 22], fixed: [0, 0], head: [-38, 14] }[ctx] as [number, number];
  const view = (p: Vec3): Vec3 => {
    const [yw, pt] = [rad(cam[0]), rad(cam[1])];
    let [x, y, z] = p;
    [x, z] = [x * Math.cos(yw) + z * Math.sin(yw), -x * Math.sin(yw) + z * Math.cos(yw)];
    [y, z] = [y * Math.cos(pt) - z * Math.sin(pt), y * Math.sin(pt) + z * Math.cos(pt)];
    return [x, y, z];
  };
  // where the context puts the model: the display transform, then the renderer's own placement (approximate)
  const place = (v: Vec3): Vec3 => {
    const p = applyDisplay(t, v);
    if (ctx === "fixed") return [-p[0], p[1], -p[2]]; // the frame faces the viewer from the item's back side (vanilla fixed has a 180 y turn)
    if (ctx === "head") return [p[0] * 0.625, p[1] * 0.625 + 4, p[2] * 0.625]; // head layer: scale 0.625 about the neck pivot
    return p;
  };
  const quads = itemQuads(r, place);
  const back: Q[] = [];
  if (ctx === "gui") {
    const s = 9, z = -12;
    back.push({ w: [[-s, -s, z], [s, -s, z], [s, s, z], [-s, s, z]], fill: ARM.slotLo, part: "arm", bias: -2 });
    back.push({ w: [[-s + 1, -s, z + 0.1], [s, -s, z + 0.1], [s, s - 1, z + 0.1], [-s + 1, s - 1, z + 0.1]], fill: ARM.slotHi, part: "arm", bias: -2 });
    back.push({ w: [[-s + 1, -s + 1, z + 0.2], [s - 1, -s + 1, z + 0.2], [s - 1, s - 1, z + 0.2], [-s + 1, s - 1, z + 0.2]], fill: ARM.slotIn, part: "arm", bias: -2 });
  } else if (ctx === "ground") {
    let lo = Infinity; for (const q of quads) for (const p of q.w) lo = Math.min(lo, p[1]);
    const gy = (Number.isFinite(lo) ? lo : 0) - 2;
    const pts: Vec3[] = Array.from({ length: 20 }, (_, i) => [Math.cos((i / 20) * 2 * Math.PI) * 5, gy, Math.sin((i / 20) * 2 * Math.PI) * 5]);
    back.push({ w: pts, fill: "#00000055", part: "arm", bias: -2 });
  } else if (ctx === "fixed") {
    const s = 8, z = -2;
    back.push({ w: [[-s, -s, z], [s, -s, z], [s, s, z], [-s, s, z]], fill: ARM.frame, part: "arm", bias: -2, stroke: ARM.edge });
    back.push({ w: [[-s + 2, -s + 2, z + 0.1], [s - 2, -s + 2, z + 0.1], [s - 2, s - 2, z + 0.1], [-s + 2, s - 2, z + 0.1]], fill: ARM.frameIn, part: "arm", bias: -2 });
  } else if (ctx === "head") {
    back.push(...box([0, 4, 0], [8, 8, 8], { top: ARM.skinTop, side: ARM.skinSide, front: ARM.skin }).map((q) => ({ ...q, bias: 0 })));
    back.push(...box([0, -6, 0], [8, 12, 4], { top: ARM.skinTop, side: shade(ARM.skinSide, 0.85), front: shade(ARM.skin, 0.85) }).map((q) => ({ ...q, bias: -1 })));
  }
  const all = [...back, ...quads].map((q) => {
    const ps = q.w.map(view);
    return { pts: ps.map((p) => [p[0], -p[1]] as [number, number]), fill: q.fill, depth: ps.reduce((s2, p) => s2 + p[2], 0) / ps.length, part: q.part, bias: q.bias, ...(q.stroke ? { stroke: q.stroke } : {}) };
  }).sort((a, b) => a.bias - b.bias || a.depth - b.depth);
  // fit (the backdrop included, so the slot / frame / head stay in frame)
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  for (const p of all) for (const [x, y] of p.pts) { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); }
  const m = 12, sc = Math.min((W - 2 * m) / (x1 - x0 || 1), (H - 2 * m) / (y1 - y0 || 1));
  const ox = (W - (x1 - x0) * sc) / 2 - x0 * sc, oy = (H - (y1 - y0) * sc) / 2 - y0 * sc;
  return { polys: all.map((p) => ({ pts: p.pts.map(([x, y]) => [x * sc + ox, y * sc + oy] as [number, number]), fill: p.fill, depth: p.depth, part: p.part, ...(p.stroke ? { stroke: p.stroke } : {}) })) };
}

