docs/DOCUMENTATION.md:22546:- Playwright interaction tests `test/e2e/cyrus-studios.e2e.mjs` (24/24 passed: pencil stroke = one step, paint count, undo / redo shortcuts, tool keys, fake candidate as a split compare layer, accept, save, history after reload, library "use in project", narrow review + approve, Katara narrow lock, Saka locked + API 403, Saka sound included, Free sound locked, plan-unknown fails closed with assets visible, non-preview account not-found + API 404). Screenshots `test/e2e/cyrus-studios.shots.mjs` -> `/root/agent-notes/cyrus-designs/impl-shots/` (24). How to run: the header of both scripts (fixtures `scripts/cyrus/studio-fixtures.ts`, devhost throwaway DB only; env `CYRUS_STUDIO_CANDIDATES=fake CYRUS_UPLOAD_STORE=local CYRUS_STUDIO_TEST_PLAN_UNKNOWN=usr_studio_unknown CYRUS_MANAGED_PLUGINS_REAL=1` for the "hosted" pack state).

  await db.user.upsert({ where: { id: p.id }, update: {}, create: { id: p.id, email: p.email, name: p.email.split("@")[0], passwordHash: "x", emailVerifiedAt: new Date(), heardAboutUs: "other" } as never });
  await db.cyrusTokenAccount.upsert({ where: { userId: p.id }, update: { tierOverride: p.tier, balance: 250 }, create: { userId: p.id, balance: 250, lifetimeGranted: 250, tierOverride: p.tier } });
  if (await db.modBuild.count({ where: { userId: p.id } })) throw new Error("already seeded: run `devhost db reset && devhost db push` first");
  const meta = { title: "Banshee Hunt", category: "creatures", categorySource: "owner", description: "A wailing banshee that haunts the night, and the handgun to stop it." };
  const v1 = await db.modBuild.create({ data: { userId: p.id, status: "succeeded", prompt: "A wailing banshee mob that haunts the night, and a 9mm handgun to stop it.", mcVersion: "1.21.11", pluginName: "BansheeHunt", version: "1.0.0", cyrus: meta, result: { summary: "Banshee mob + handgun" }, jarName: "BansheeHunt-1.0.0.jar", jarSha256: "a".repeat(64), createdAt: new Date(Date.now() - 2 * 86400e3) } });
  const project = await createProject({ userId: p.id, game: "minecraft", rootBuildId: v1.id });
  const glockSha = sha256Hex(canonicalJson(GLOCK));
  const rev = await addRevision(project.id, {
    kind: "generated", status: "passed", modBuildId: v1.id, expectedHeadId: null, message: "1 custom texture; pack seeded",
    manifest: [{ path: "plugin/BansheeHunt-1.0.0.jar", sha256: "a".repeat(64), role: "artifact" }, { path: "assets/textures/glock_9mm.json", sha256: glockSha, role: "asset" }, { path: `resourcepack/${"b".repeat(40)}.zip`, sha256: "c".repeat(64), role: "resourcePack" }],
  });
  await recordAsset(project.id, { revisionId: rev.id, assetKey: "glock_9mm", kind: "texture", sha256: glockSha, size: canonicalJson(GLOCK).length, origin: "generated", mime: TEXTURE_SPEC_MIME, path: "assets/textures/glock_9mm.json",
    provenance: { generator: "cyrus-texture-dsl", spec: GLOCK, quality: textureQuality(render(GLOCK)), pngSha256: sha256Hex(encodePng(render(GLOCK))), modBuildId: v1.id, kept: false } });
  const assets: MbAssets = {
    status: "ready", namespace: project.namespace, projectId: project.id, revisionId: rev.id,
    textures: [{ name: "glock_9mm", model: `${project.namespace}:glock_9mm`, specSha256: glockSha, pngSha256: "d".repeat(64), quality: "warn" }],
    sounds: SOUNDS.map((s) => ({ ...s, key: `${project.namespace}:${s.set}.${s.event}` })), soundRender: "rendered", dropped: [],
    pack: { sha1: "b".repeat(40), sha256: "c".repeat(64), bytes: 48213, format: 75, clientVerified: false, url: `https://packs.example.test/p/${"b".repeat(40)}.zip` },
    loader: { id: `${project.namespace}-main`, url: `https://packs.example.test/p/${"b".repeat(40)}.zip`, sha1: "b".repeat(40), prompt: "Banshee Hunt uses custom item textures and sounds.", required: false }, notices: [],
  };
  await db.modBuild.update({ where: { id: v1.id }, data: { result: { summary: "Banshee mob + handgun", assets } as never } });
  // two more textures from the texture library, through the studio's own save path (library origin)
  const deps: StudioServiceDeps = { store: prismaStudioStore, planOf: async () => "all", chain: chainOf, deliveryOn: () => false };
  for (const [itemId, key] of [["ghost_veil_ecto", "banshee_veil"], ["gem_azure", "soul_gem"]] as const) {
    const used = await useTextureFromLibrary({ itemId, key, namespace: project.namespace }, (k, path) => prismaStudioStore.reserve(project.id, k, path));
    if (!used.ok) throw new Error(used.error);
    const head = (await db.cyrusProject.findUnique({ where: { id: project.id } }))!.headRevisionId;
    await saveTexture(deps, { userId: p.id, projectId: project.id, key, doc: docFromSpec(used.spec), baseAssetId: null, expectedHeadId: head, origin: "library", provenance: { library: used.provenance.library } });
  }
  // a Cyrus candidate for glock_9mm, shaped exactly like the real backend's (a change build with the studio marker +
  // the texture row the asset sync records for it): drops the grip noise (Style DNA) and brightens the front sight
  const cand = { ...GLOCK, ops: [...GLOCK.ops.filter((o) => o.op !== "noise").slice(0, -2), { op: "px" as const, x: 26, y: 8, c: "o" }, ...GLOCK.ops.slice(-2)] };
  const cb = await db.modBuild.create({ data: { userId: p.id, status: "succeeded", prompt: v1.prompt, changeRequest: candidateRequestText("glock_9mm", "Remove the grip noise and brighten the front sight"), baseBuildId: v1.id, rootBuildId: v1.id, mcVersion: "1.21.11", pluginName: "BansheeHunt", version: "1.0.1", cyrus: meta, result: { summary: "texture edit" } } });
  const candSha = sha256Hex(canonicalJson(cand));
  const head = (await db.cyrusProject.findUnique({ where: { id: project.id } }))!.headRevisionId;
  const crev = await addRevision(project.id, { kind: "generated", status: "passed", modBuildId: cb.id, expectedHeadId: head, message: "candidate build", manifest: [{ path: "assets/textures/glock_9mm.json", sha256: candSha, role: "asset" }] });
  await recordAsset(project.id, { revisionId: crev.id, assetKey: "glock_9mm", kind: "texture", sha256: candSha, size: canonicalJson(cand).length, origin: "generated", mime: TEXTURE_SPEC_MIME, path: "assets/textures/glock_9mm.json", provenance: { generator: "cyrus-texture-dsl", spec: cand, modBuildId: cb.id, kept: false } });
  return { userId: p.id, buildId: v1.id, projectId: project.id };
}

(async () => {
  await db.setting.upsert({ where: { key: "preview_access_emails_modbuilder" }, update: { value: PLANS.filter((p) => p.id !== "usr_studio_outsider").map((p) => p.email).join(",") }, create: { key: "preview_access_emails_modbuilder", value: PLANS.filter((p) => p.id !== "usr_studio_outsider").map((p) => p.email).join(",") } });
  await db.setting.upsert({ where: { key: "cyrus_studios_enabled" }, update: { value: "false" }, create: { key: "cyrus_studios_enabled", value: "false" } });
  const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
  const out: Record<string, unknown> = { cookie: process.env.NXEON_COOKIE_NAME ?? "nxeon_session" };
  for (const p of PLANS) {
